private object ThreadReactionGlyphDiagnostics {
    private val loggedKeys = mutableSetOf<String>()

    fun logOnce(path: String, emoji: String, detail: String) {
        val key = "$path:$emoji:$detail"
        if (loggedKeys.add(key)) {
            Utils.logToNative("thread_reaction_glyph path=$path emoji=$emoji $detail")
        }
    }

    // task #379: one-shot readiness signal for the visual-testing capture harness.
    // The reaction sprite atlas decodes asynchronously; in the headless capture
    // environment the snapshot can be taken before it finishes, so every reaction
    // renders as a raw-emoji fallback. Emitting this line once (when the hoisted
    // atlas ImageBitmap first becomes non-null) gives the capture side a logcat
    // token to wait on before snapshotting reaction-bearing cases.
    fun logAtlasReadyOnce(width: Int, height: Int) {
        if (loggedKeys.add("thread_reaction_atlas_ready")) {
            Utils.logToNative("thread_reaction_atlas_ready imageWidth=$width imageHeight=$height")
        }
    }
}

internal fun threadComposerBottomPadding(
    keyboardInsetDp: Float,
    bottomSafeArea: Dp,
    keyboardInsetExcludesBottomSafeArea: Boolean = false
): Dp {
    val keyboardInset = keyboardInsetDp.coerceAtLeast(0f).dp
    // When the keyboard height already contains the bottom safe area (iOS keyboard frame), the
    // keyboard and the safe area overlap: the composer sits on whichever is taller. Taking the max
    // (instead of switching from safe area to keyboard as soon as the keyboard is > 0) keeps the
    // padding from dipping below its resting value during the first frames of the keyboard
    // animation, while the keyboard is still shorter than the safe area.
    val bottomInset =
        if (keyboardInsetExcludesBottomSafeArea) {
            keyboardInset + bottomSafeArea
        } else {
            maxOf(keyboardInset, bottomSafeArea)
        }
    return ThreadComposerBottomBasePadding + ThreadComposerBottomSafeAreaLift + bottomInset
}

internal fun threadChannelHeaderSubtitle(channelName: String?): String? {
    val raw = channelName?.trim().orEmpty()
    if (raw.isBlank() || raw.startsWith("Origin:", ignoreCase = true)) return null
    val name = raw.removePrefix("#").substringBefore(":").trim()
    if (name.isBlank()) return null
    if (name.equals(ThreadReplyPageTitle, ignoreCase = true)) return null
    if (name.equals("Threads", ignoreCase = true)) return null
    if (name.equals("Thread", ignoreCase = true) || name.equals("Channel", ignoreCase = true)) return null
    if (threadHeaderIdentityLikeTitle(name)) return null
    return "#$name"
}

internal fun existingThreadChannelHeaderSubtitle(subtitle: String?): String? =
    subtitle?.trim()?.takeIf { it.startsWith("#") }?.let(::threadChannelHeaderSubtitle)

internal fun threadHeaderDisplayTitle(
    title: String?,
    surfaceKind: String = RaftThreadSurfaceKind.Channel
): String =
    threadHeaderSafeTitleOrNull(title) ?: threadHeaderFallbackTitle(surfaceKind)

/** task #36: longest wait for the keyboard to close before the main detail focuses a parent. */
private const val ADAPTIVE_PARENT_FOCUS_IME_WAIT_MS = 1_500L

@Page(THREAD_PAGE, supportInLocal = true)
internal class ComposeThreadPage : AuthenticatedProductPager(AuthenticatedProductRoute.Thread) {
    /**
     * Latest host window fact (A4 adoption, task #18). Standalone thread pages are the only
     * initiation source: the fact is captured here at the pager boundary and reduced by the
     * screen so a DualPane arrival can trigger one guarded prepare/commit transaction.
     */
    private var adaptivePaneState by mutableStateOf(RaftAdaptivePaneState())
    private var adaptivePaneEvent by mutableStateOf<RaftAdaptivePaneEvent?>(null)

    override fun willInit() {
        super.willInit()
        setAuthenticatedContent {
            RaftInputFocusDismissHost { focusDismissModifier ->
                Box(modifier = focusDismissModifier.fillMaxSize()) {
                    ThreadPageScreen(
                        pageVisibleTick = raftPageVisibleResumeTick,
                        pageVisible = raftPageVisible,
                        adaptivePaneState = adaptivePaneState,
                        adaptivePaneEvent = adaptivePaneEvent,
                    )
                }
            }
        }
    }

    override fun onRaftAdaptivePaneChanged(eventData: JSONObject) {
        val event = eventData.toRaftAdaptivePaneEventOrNull() ?: return
        adaptivePaneState = reduceRaftAdaptivePane(adaptivePaneState, event)
        adaptivePaneEvent = event
    }
}

