internal fun TaskSummary.threadLinkedTaskAssigneeDisplayName(): String? {
    val assignee = assignee ?: return null
    val assigneeId = assignee.id.value.trim().removePrefix("@").takeIf { it.isNotBlank() }
    val displayName = assignee.displayName.trim().removePrefix("@").takeIf { it.isNotBlank() } ?: return null
    if (assigneeId != null && displayName.equals(assigneeId, ignoreCase = true)) return null
    return displayName.takeIf { it.isDisplaySafeTaskAssigneeName(assigneeId) }
}

internal fun RaftThreadScreenPayload.supportsChannelTasks(): Boolean =
    composer.showAsTaskToggle || showTaskOpenActions || showTaskStatusActions

internal sealed interface MarkdownTaskNumberOpenResult {
    data class Found(
        val task: TaskSummary,
        val payload: RaftThreadScreenPayload,
        val source: SharedTaskReferenceResolutionSource
    ) : MarkdownTaskNumberOpenResult

    data class Ambiguous(
        val taskNumber: Int,
        val candidates: List<TaskSummary>,
        val source: SharedTaskReferenceResolutionSource
    ) : MarkdownTaskNumberOpenResult

    data object NotFound : MarkdownTaskNumberOpenResult
    data object AuthRequired : MarkdownTaskNumberOpenResult
    data object Failed : MarkdownTaskNumberOpenResult
}

internal class MarkdownTaskNumberOpenRequestGate {
    private var generation: Long = 0L

    fun nextRequest(): Long {
        generation += 1L
        return generation
    }

    fun <T> accept(requestGeneration: Long, value: T): T? =
        value.takeIf { requestGeneration == generation }
}

internal suspend fun openMarkdownTaskNumberPayload(
    serverId: ServerId,
    taskNumber: Int,
    currentPayload: RaftThreadScreenPayload,
    currentTaskChannelId: ChannelId?,
    tasksDataSource: SharedTasksDataSource,
    tasksDataStore: SharedTasksDataStore?,
    conversationIdentityProvider: SharedConversationIdentityProvider? = null
): MarkdownTaskNumberOpenResult {
    return when (
        val resolution =
            resolveSharedTaskReference(
                serverId = serverId,
                taskNumber = taskNumber,
                currentChannelId = currentTaskChannelId,
                tasksDataSource = tasksDataSource,
                tasksDataStore = tasksDataStore
            )
    ) {
        is SharedTaskReferenceResolution.Found -> {
            val payload =
                currentPayload.taskThreadLaunchPayload(
                    task = resolution.task,
                    serverId = serverId,
                    conversationIdentityProvider = conversationIdentityProvider
                ) ?: return MarkdownTaskNumberOpenResult.Failed
            MarkdownTaskNumberOpenResult.Found(
                task = resolution.task,
                payload = payload,
                source = resolution.source
            )
        }
        is SharedTaskReferenceResolution.Ambiguous ->
            MarkdownTaskNumberOpenResult.Ambiguous(
                taskNumber = resolution.taskNumber,
                candidates = resolution.candidates,
                source = resolution.source
            )
        SharedTaskReferenceResolution.NotFound -> MarkdownTaskNumberOpenResult.NotFound
        SharedTaskReferenceResolution.AuthRequired -> MarkdownTaskNumberOpenResult.AuthRequired
        SharedTaskReferenceResolution.Failed -> MarkdownTaskNumberOpenResult.Failed
    }
}

/**
 * Canonical task-to-thread opener shared by the Tasks panel and Markdown task references.
 *
 * A task row already carries the typed parent/stream identity required by the same
 * [resolveOpenRequest] contract used by Activity. Keep that identity intact instead of
 * reducing the row to a task id and searching only the currently loaded message window.
 */
internal fun RaftThreadScreenPayload.taskThreadLaunchPayload(
    task: TaskSummary,
    serverId: ServerId,
    conversationIdentityProvider: SharedConversationIdentityProvider? = null
): RaftThreadScreenPayload? {
    val taskIds = listOfNotNull(task.threadId?.value, task.channelId?.value).filter { it.isNotBlank() }
    val directory =
        taskIds
            .mapNotNull { id -> conversationIdentityProvider?.resolveProjection(serverId, id) }
            .distinctBy { it.canonicalChannelId }
            .toSharedConversationDirectoryState()
    val currentRoute = resolveThreadRouteIdentity()
    val taskParentId = task.channelId?.value?.takeIf { it.isNotBlank() }
    val currentParentKind =
        if (taskParentId != null && taskParentId == currentRoute.timelineChannelId) {
            parseConversationKindOrNull(currentRoute.routeKind)
        } else if (
            taskParentId != null &&
            currentRoute.surfaceKind == RaftThreadSurfaceKind.ReplyThread &&
            parentChannelId == taskParentId
        ) {
            currentRoute.parentConversationKind
        } else {
            null
        }
    val launchPayload =
        buildStandaloneTaskThreadLaunchPayload(
            task = task,
            serverId = serverId.value,
            conversationDirectory = directory,
            timeContext =
                RaftTimeContext(
                    localOffsetMinutes = localOffsetMinutes,
                    todayEpochDay = todayEpochDay,
                    nowEpochMillis = nowEpochMillis,
                    timeFormat = timeFormat
                ),
            alignOwnMessagesRight = alignOwnMessagesRight,
            compactConsecutiveMessages = compactConsecutiveMessages,
            parentConversationKind = currentParentKind
        ) ?: return null
    return launchPayload.toInitialPayloadOrNull(launchPayload.instanceId)
}

internal fun RaftThreadScreenPayload.canConvertMessagesToTasks(): Boolean =
    showTaskStatusActions &&
        !surfaceKind.equals(RaftThreadSurfaceKind.ReplyThread, ignoreCase = true) &&
        parentMessageId.isNullOrBlank() &&
        originParentMessageId.isNullOrBlank()

internal fun RaftThreadMessageItem.canConvertToTask(): Boolean =
    !isSystemMessage() &&
        taskId.isNullOrBlank() &&
        taskNumber == null &&
        !hasLocalSendState()

internal fun shouldStartThreadTasksJoin(
    payload: RaftThreadScreenPayload,
    startedThreadId: String?,
    taskChannelId: ChannelId?
): Boolean =
    shouldStartThreadTasksLoad(payload, taskChannelId) &&
        RaftThreadTab.fromWireValue(payload.selectedTab) == RaftThreadTab.Tasks &&
        startedThreadId != taskChannelId?.value

internal fun shouldStartThreadTasksLoad(
    payload: RaftThreadScreenPayload,
    taskChannelId: ChannelId?
): Boolean =
    taskChannelId != null &&
        payload.status == "content" &&
        payload.supportsChannelTasks() &&
        payload.resolvedTaskLookupChannelId()?.let { it == taskChannelId.value } == true

internal fun shouldRefreshThreadTasksProjection(
    payload: RaftThreadScreenPayload,
    taskChannelId: ChannelId?,
    refreshStarted: Boolean
): Boolean =
    shouldStartThreadTasksLoad(payload, taskChannelId) &&
        RaftThreadTab.fromWireValue(payload.selectedTab) == RaftThreadTab.Chat &&
        !refreshStarted

internal fun RaftThreadScreenPayload.resolvedAuxiliaryThreadId(): String? {
    val timelineChannelId = resolveThreadRouteIdentity().timelineChannelId ?: return null
    if (!isReplyThreadWithExplicitParentPair()) return timelineChannelId
    if (status == "loading") return null
    return timelineChannelId
}

internal fun RaftThreadScreenPayload.resolvedTaskLookupChannelId(
    writeActionsEnabled: Boolean = true
): String? {
    if (!writeActionsEnabled) return null
    val timelineChannelId = resolvedAuxiliaryThreadId() ?: return null
    if (!isReplyThreadWithExplicitParentPair()) return timelineChannelId
    return parentChannelId.nonBlank() ?: timelineChannelId
}

internal fun RaftThreadScreenPayload.replyParentChannelIdForNestedOpen(): String? =
    if (isReplyThreadWithExplicitParentPair()) {
        parentChannelId.nonBlank()
    } else {
        sourceThreadId.nonBlank()
            ?: streamChannelId.nonBlank()
            ?: parentChannelId.nonBlank()
    }

private fun RaftThreadScreenPayload.isReplyThreadWithExplicitParentPair(): Boolean =
    surfaceKind == RaftThreadSurfaceKind.ReplyThread &&
        parentChannelId.nonBlank() != null &&
        replyParentMessageIdForAuxiliary() != null

private fun RaftThreadScreenPayload.replyParentMessageIdForAuxiliary(): String? =
    parentMessageId.nonBlank() ?: originParentMessageId.nonBlank()

private fun RaftThreadScreenPayload.threadRenderDiagnosticsSource(): String =
    threadRenderDiagnosticsSource(toThreadTimelineSlice())

private fun RaftThreadScreenPayload.threadRenderDiagnosticsSource(timelineSlice: ThreadTimelineSlice): String =
    when {
        status == "loading" -> "loading"
        status == "content" && timelineSlice.messages.isNotEmpty() -> "content"
        status == "content" -> "empty_content"
        isRenderableEmptyReplyThread() -> "empty_reply"
        errorCode != null -> "error"
        else -> status.ifBlank { "unknown" }
    }

private fun RaftThreadScreenPayload.isRenderableEmptyReplyThread(): Boolean =
    status == "empty" && surfaceKind == RaftThreadSurfaceKind.ReplyThread

private fun RaftThreadScreenPayload.isReadyForThreadPerformanceGate(): Boolean =
    status == "content" || isRenderableEmptyReplyThread()

internal const val ThreadPayloadReadyBudgetMs = 1_500L
internal const val ThreadFirstLayoutBudgetMs = 100L
internal const val ThreadFirstDrawBudgetMs = 100L

internal class ThreadPerformanceGenerationCounter {
    private var reconcileGeneration = 0L
    private var layoutGeneration = 0L
    private var lastLayoutReconcileGeneration = -1L
    private var lastWidth = -1
    private var lastHeight = -1

    fun nextReconcile(): Long = ++reconcileGeneration

    fun nextLayout(width: Int, height: Int): ThreadLayoutGeneration? {
        if (
            lastLayoutReconcileGeneration == reconcileGeneration &&
            lastWidth == width &&
            lastHeight == height
        ) {
            return null
        }
        lastLayoutReconcileGeneration = reconcileGeneration
        lastWidth = width
        lastHeight = height
        return ThreadLayoutGeneration(
            generation = ++layoutGeneration,
            reconcileGeneration = reconcileGeneration
        )
    }
}

internal data class ThreadLayoutGeneration(
    val generation: Long,
    val reconcileGeneration: Long
)

internal data class ThreadFirstContentPerformanceBudgetResult(
    val payloadReadyWithinBudget: Boolean?,
    val layoutWithinBudget: Boolean?,
    val drawWithinBudget: Boolean?
) {
    val passed: Boolean
        get() {
            val measurements =
                listOfNotNull(
                    payloadReadyWithinBudget,
                    layoutWithinBudget,
                    drawWithinBudget
                )
            return measurements.isNotEmpty() && measurements.all { it }
        }
}

internal fun evaluateThreadFirstContentPerformanceBudget(
    payloadReadyMs: Long? = null,
    layoutMs: Long? = null,
    drawMs: Long? = null
): ThreadFirstContentPerformanceBudgetResult =
    ThreadFirstContentPerformanceBudgetResult(
        payloadReadyWithinBudget = payloadReadyMs?.let { it <= ThreadPayloadReadyBudgetMs },
        layoutWithinBudget = layoutMs?.let { it <= ThreadFirstLayoutBudgetMs },
        drawWithinBudget = drawMs?.let { it <= ThreadFirstDrawBudgetMs }
    )

private fun requestKuiklyThreadPerformanceSnapshot(
    bridge: build.raft.app.base.BridgeModule,
    threadId: String,
    reason: String,
    status: String
) {
    runCatching {
        PagerManager.getCurrentPager()
            .acquireModule<PerformanceModule>(PerformanceModule.MODULE_NAME)
            .getPerformanceData { data ->
                val layoutMs = data?.pageLoadTime?.pageLayoutCost?.toLong()
                val drawMs = data?.pageLoadTime?.renderCost?.toLong()
                val budget =
                    evaluateThreadFirstContentPerformanceBudget(
                        layoutMs = layoutMs,
                        drawMs = drawMs
                    )
                val summary = bridge.reportKuiklyPerformanceSnapshot(
                    routeName = "kuikly_thread",
                    reason = reason,
                    threadId = threadId,
                    data = data
                )
                bridge.performanceMarker(
                    phase = "thread_first_frame",
                    routeName = "kuikly_thread",
                    event = "instant",
                    threadId = threadId,
                    durationMs = data?.pageLoadTime?.firstPaintCost?.toLong(),
                    metadata =
                        mapOf(
                            "reason" to reason,
                            "status" to status,
                            "layoutBudgetMs" to ThreadFirstLayoutBudgetMs.toString(),
                            "drawBudgetMs" to ThreadFirstDrawBudgetMs.toString(),
                            "layoutWithinBudget" to budget.layoutWithinBudget.toString(),
                            "drawWithinBudget" to budget.drawWithinBudget.toString()
                        )
                )
                bridge.log("kuikly_perf_snapshot $summary")
                bridge.log(
                    "thread_first_content_budget phase=render layoutMs=${layoutMs ?: -1} " +
                        "drawMs=${drawMs ?: -1} layoutBudgetMs=$ThreadFirstLayoutBudgetMs " +
                        "drawBudgetMs=$ThreadFirstDrawBudgetMs pass=${budget.passed}"
                )
            }
    }.onFailure { error ->
        val summary = bridge.reportKuiklyPerformanceSnapshot(
            routeName = "kuikly_thread",
            reason = reason,
            threadId = threadId,
            data = null,
            statusOverride = "failed"
        )
        bridge.performanceMarker(
            phase = "thread_first_frame",
            routeName = "kuikly_thread",
            event = "instant",
            threadId = threadId,
            metadata =
                mapOf(
                    "reason" to reason,
                    "status" to "failed"
                )
        )
        bridge.log("kuikly_perf_snapshot $summary error=${error.message.orEmpty()}")
    }
}

private enum class RaftThreadTab(val wireValue: String, val label: String) {
    Chat("chat", "Chat"),
    Tasks("tasks", "Tasks"),
    Files("files", "Files");

    companion object {
        fun fromWireValue(value: String?): RaftThreadTab =
            entries.firstOrNull { it.wireValue == value?.trim()?.lowercase() } ?: Chat
    }
}

private val ThreadResolvedContentStatuses = setOf("content", "empty")

internal fun shouldShowThreadComposerForTab(
    joined: Boolean,
    showComposer: Boolean,
    selectedTab: String?
): Boolean =
    joined &&
        showComposer &&
        RaftThreadTab.fromWireValue(selectedTab) == RaftThreadTab.Chat

internal fun shouldShowThreadComposerForReadyContent(
    joined: Boolean,
    showComposer: Boolean,
    selectedTab: String?
): Boolean =
    shouldShowThreadComposerForTab(joined, showComposer, selectedTab)

internal fun RaftThreadScreenPayload.hasRenderableContentForComposer(): Boolean =
    hasRenderableContentForComposer(
        timelineSlice = toThreadTimelineSlice(),
        accessResolution = ThreadAccessResolution.Resolved
    )

internal fun RaftThreadScreenPayload.hasRenderableContentForComposer(
    timelineSlice: ThreadTimelineSlice,
    accessResolution: ThreadAccessResolution = ThreadAccessResolution.Resolved
): Boolean =
    isThreadPrimaryFooterReady(timelineSlice, accessResolution)

internal fun RaftThreadScreenPayload.isThreadPrimaryFooterReady(
    timelineSlice: ThreadTimelineSlice,
    accessResolution: ThreadAccessResolution
): Boolean =
    accessResolution == ThreadAccessResolution.Resolved &&
        status in ThreadResolvedContentStatuses &&
        timelineSlice.status in ThreadResolvedContentStatuses &&
        !shouldRenderThreadEarlyLoadingShell(timelineSlice)

internal fun shouldDeliverToActiveThreadRealtimeSignal(event: RealtimeEvent): Boolean =
    RealtimeRoutePolicy.shouldForwardToActiveThread(event) || event is Heartbeat

private fun RealtimeEvent.isTaskProjectionEvent(): Boolean =
    this is TaskCreated || this is TaskUpdated || this is TaskDeleted

private val RaftThreadTab.icon: RaftLucideIconName
    get() =
        when (this) {
            RaftThreadTab.Chat -> RaftLucideIconName.MessageSquare
            RaftThreadTab.Tasks -> RaftLucideIconName.ListTodo
            RaftThreadTab.Files -> RaftLucideIconName.Paperclip
        }

@Composable
private fun RaftThreadTab.toRaftTabSpec(): RaftTabSpec<RaftThreadTab> =
    RaftTabSpec(
        key = this,
        label =
            when (this) {
                RaftThreadTab.Chat -> stringResource(MR.strings.thread_tab_chat)
                RaftThreadTab.Tasks -> stringResource(MR.strings.thread_tab_tasks)
                RaftThreadTab.Files -> stringResource(MR.strings.thread_tab_files)
            },
        iconName = icon
    )

@OptIn(ExperimentalUuidApi::class)
@Composable
private fun ThreadPageScreen(
    pageVisibleTick: Int,
    pageVisible: Boolean,
    adaptivePaneState: RaftAdaptivePaneState = RaftAdaptivePaneState(),
    adaptivePaneEvent: RaftAdaptivePaneEvent? = null,
) {
    val pager = LocalActivity.current.getPager() as Pager
    val bridge = Utils.bridgeModule(pager.pagerId)
    val params = pager.pageData.params
    var payloadText by remember { mutableStateOf(params.optString("payload")) }
    var instanceId by remember { mutableStateOf(params.optString("instanceId")) }
    var adaptiveCloseRequest by remember {
        mutableStateOf(params.toRaftAdaptiveDetailCloseRequestOrNull())
    }
    DisposableEffect(pager) {
        val observer =
            object : IPagerEventObserver {
                override fun onPagerEvent(pagerEvent: String, eventData: JSONObject) {
                    if (pagerEvent != THREAD_PAGE_DATA_EVENT) return
                    eventData.optString("payload").takeIf { it.isNotBlank() }?.let { payloadText = it }
                    eventData.optString("instanceId").takeIf { it.isNotBlank() }?.let { instanceId = it }
                    adaptiveCloseRequest =
                        updatedRaftAdaptiveDetailCloseRequest(adaptiveCloseRequest, eventData)
                }
            }
        pager.addPagerEventObserver(observer)
        onDispose { pager.removePagerEventObserver(observer) }
    }
    val payloadTrace = remember(payloadText, instanceId) {
        parseThreadScreenPayloadWithTrace(
            payload = payloadText,
            instanceId = instanceId
        )
    }
    val parsedPayload = payloadTrace.payload
    val liveTimeContextProvider =
        rememberLiveRaftTimeContext(
            capabilities = parsedPayload.toRaftTimeCapabilities(),
            pageVisibleTick = pageVisibleTick,
            active = pageVisible
        )
    val payload = parsedPayload
    LaunchedEffect(payloadText, instanceId) {
        bridge.log(
            "thread_launch_payload_parse source=pageData result=${payloadTrace.result} " +
                "responseBytes=${payloadTrace.responseBytes} durationMs=${payloadTrace.durationMs} dispatcher=caller"
        )
    }
    val storeScope = remember(params.toString(), pager.pagerId) {
        params.raftShellStoreScope(RaftShellStoreScope.Legacy.shellInstanceId)
    }
    val sharedStores = remember { RaftSharedStoreRegistry.get(bridge) }

    // A4 adoption (task #18): only a standalone (native-stack) page initiates. The embedded
    // detail child is identified by RAFT_EMBEDDED_CHILD_PAGE_PARAM, injected by
    // raftEmbeddedChildPageData for every RaftChildPage mount — not by shell scope
    // presence, which every openRaftPage-pushed page also carries.
    val isStandaloneThreadPage =
        adaptiveCloseRequest == null &&
            !params.optBoolean(RAFT_EMBEDDED_CHILD_PAGE_PARAM, false)
    val adaptiveInitiationEnabled =
        params.optBoolean(RAFT_ADAPTIVE_INITIATION_ENABLED, false)
    val adaptiveInitiationCaptureHolder =
        remember { ThreadAdaptiveInitiationCaptureHolder() }
    val adaptiveNativeEditingStateReader =
        remember { RaftTextFieldNativeEditingStateReader() }
    val adaptiveDetailOpenInitiator =
        remember(storeScope.shellInstanceId, pager.pagerId, isStandaloneThreadPage) {
            if (!isStandaloneThreadPage) return@remember null
            RaftAdaptiveDetailOpenInitiator(
                shellInstanceId = storeScope.shellInstanceId,
                hostId = "pager:${pager.pagerId}",
                anchorStore = sharedStores.adaptiveScrollAnchorStore(storeScope),
                eventBus = sharedStores.eventBus,
                nowEpochMillis = { defaultNowMillis() },
                nativeAdaptiveNavigation = { action, requestId, token, expectedRefTag, expectedText ->
                    bridge.adaptiveNavigation(
                        action = action,
                        requestId = requestId,
                        token = token,
                        // Caller-cancelled prepare still owns its nonce: a late prepared
                        // reply must retire the accepted transaction, not orphan it into
                        // request_in_progress.
                        onLateReply = { reply ->
                            val lateToken = reply.optString("token").trim()
                            if (
                                action == "prepare" &&
                                reply.optString("status") == "prepared" &&
                                lateToken.isNotBlank()
                            ) {
                                bridge.dispatchAdaptiveCancel(requestId, lateToken)
                            }
                        },
                        expectedEditorRefTag = expectedRefTag,
                        expectedEditorText = expectedText,
                    )
                },
                dispatchAdaptiveCommit = { requestId, token ->
                    bridge.dispatchAdaptiveCommit(requestId, token)
                },
                dispatchAdaptiveCancel = { requestId, token ->
                    bridge.dispatchAdaptiveCancel(requestId, token)
                },
                captureLatestDraft = captureLatestDraftForAdoption@{ requestId ->
                    val capture =
                        adaptiveInitiationCaptureHolder.captureLatestDraft
                            ?: return@captureLatestDraftForAdoption null
                    capture(requestId)
                },
                captureAnchor = captureAnchorForAdoption@{ requestId ->
                    adaptiveInitiationCaptureHolder.captureAnchor?.invoke(requestId)
                },
                log = { message -> bridge.log("adaptive_initiate $message") },
                logWarn = { message -> bridge.logWarn("adaptive_initiate $message") },
            )
        }
    LaunchedEffect(adaptivePaneEvent, adaptiveInitiationEnabled, isStandaloneThreadPage) {
        val event = adaptivePaneEvent ?: return@LaunchedEffect
        if (!adaptiveInitiationEnabled || !isStandaloneThreadPage) return@LaunchedEffect
        val initiator = adaptiveDetailOpenInitiator ?: return@LaunchedEffect
        if (reduceRaftAdaptivePane(adaptivePaneState, event).layout !=
            RaftAdaptivePaneLayout.DualPane
        ) {
            return@LaunchedEffect
        }
        val launchPayload =
            parsedPayload.toWireThreadLaunchPayloadOrNull() ?: return@LaunchedEffect
        val identity =
            launchPayload.toRaftAdaptiveDetailIdentity(
                serverId =
                    threadParentNavigationServerId(null)
                        ?: storeScope.initialServerId
                        ?: run {
                            bridge.logWarn(
                                "adaptive_initiate_skip reason=no_server_id pager=${pager.pagerId}"
                            )
                            return@LaunchedEffect
                        }
            ) ?: return@LaunchedEffect
        val outcome =
            initiator.initiate(
                identity = identity,
                launchPayload = launchPayload,
                windowFact = event.toRaftAdaptiveOpenWindowFact(defaultNowMillis()),
                requestId = "adopt-${pager.pagerId}-${Uuid.random()}",
            )
        bridge.log("adaptive_initiate_outcome outcome=$outcome identity=${identity.key}")
    }
    val authStore = remember(sharedStores, storeScope) { sharedStores.authStore(storeScope) }
    val serverMembersStore = remember(sharedStores, storeScope) { sharedStores.serverMembersStore(storeScope) }
    val sharedHomeStore = remember(sharedStores, storeScope) { sharedStores.sharedHomeStore(storeScope) }
    val threadPageCoroutineScope = rememberCoroutineScope()
    var authLossReportInProgress by remember { mutableStateOf(false) }
    val networkClient = remember(sharedStores, storeScope) { sharedStores.networkClient(storeScope) }
    val agentsApiClient = remember(networkClient) {
        RaftAgentsApiClient(
            transport = RaftAgentsNetworkApi(networkClient),
            diagnosticsLogger = { message -> bridge.log("thread_agents_api $message") }
        )
    }
    val computersApiClient = remember(networkClient) {
        RaftComputersApiClient(RaftComputersNetworkApi(networkClient))
    }
    val routeScope = rememberCoroutineScope()
    val createAgentCoordinator = remember(agentsApiClient, computersApiClient) {
        build.raft.app.data.SharedCreateAgentCoordinator(
            agentsApiClient = agentsApiClient,
            computersApiClient = computersApiClient,
            logger = { message -> bridge.log("thread_create_agent $message") }
        )
    }
    val memberRepository =
        remember(authStore, networkClient, serverMembersStore) {
            RealMemberRepository(
                sessionStore = authStore,
                networkClient = networkClient,
                logger = { message -> bridge.log("thread_member_repository $message") },
                cachedMembersProvider = serverMembersStore::currentServerMembers
            )
        }
    val channelRepository =
        remember(authStore, networkClient) {
            RealChannelRepository(
                sessionStore = authStore,
                networkClient = networkClient,
                warningLogger = { message -> bridge.log("thread_channel_repository $message") }
            )
        }
    val forwardTargetRepository =
        remember(authStore, networkClient, channelRepository, memberRepository) {
            RealForwardMessageTargetRepository(
                sessionStore = authStore,
                networkClient = networkClient,
                channelRepository = channelRepository,
                memberRepository = memberRepository,
                warningLogger = { message -> bridge.log("thread_forward_target_repository $message") }
            )
        }
    val membersStore =
        remember(authStore, channelRepository, routeScope) {
            SharedMembersStore(
                authStore = authStore,
                channelRepository = channelRepository,
                scope = routeScope,
                logger = { message -> bridge.log(message) }
            )
        }
    val computersStore =
        remember(computersApiClient, routeScope) {
            SharedComputersStore(
                computersApiClient = computersApiClient,
                scope = routeScope,
                logger = { message -> bridge.log("thread_$message") },
                ownerProvider = {
                    sharedStores.computersOwner(storeScope)
                }
            )
        }
    val quotedPermalinkLoader: (suspend (RaftMessagePermalinkTarget) -> RaftThreadMessageItem?)? =
        remember(networkClient) {
            val client = RaftThreadApiClient(NetworkRaftThreadApi(networkClient))
            val loader: suspend (RaftMessagePermalinkTarget) -> RaftThreadMessageItem? = { target ->
                when (val result = client.messageContext(target.messageId.value, target.channelId.value)) {
                    is ThreadApiResult.Success -> {
                        val payload = result.data
                        val targetId = payload.targetMessageId?.value ?: target.messageId.value
                        payload.messages
                            .firstOrNull { it.id.value == targetId }
                            ?.toRaftThreadMessageItem(null)
                    }
                    is ThreadApiResult.Failure -> null
                }
            }
            loader
        }
    val selectedServerStore =
        remember(sharedStores, storeScope) { sharedStores.selectedServerStore(storeScope) }
    val dataSource =
        remember(
            networkClient,
            authStore,
            selectedServerStore,
            memberRepository,
            serverMembersStore,
            channelRepository,
            sharedHomeStore,
            sharedStores.threadMessageStore,
            sharedStores.threadPendingSendJournal,
            sharedStores.apiEnvironmentStore,
            createAgentCoordinator
        ) {
            SharedThreadDataSource(
                networkApi = NetworkRaftThreadApi(networkClient),
                sessionStore = authStore,
                pendingSendJournal = sharedStores.threadPendingSendJournal,
                selectedServerStore = selectedServerStore,
                memberRepository = memberRepository,
                serverMembersStore = serverMembersStore,
                conversationRepository =
                    RealConversationRepository(
                        sessionStore = authStore,
                        networkClient = networkClient,
                        routeServerIdProvider = { selectedServerStore.selectedServerId.value },
                        warningLogger = { message -> bridge.log("thread_conversation_repository $message") }
                    ),
                channelRepository = channelRepository,
                homeSnapshotProvider =
                    sharedHomeStore?.let { store ->
                        { serverId -> store.awaitSnapshotFor(serverId, ThreadHomeSnapshotAwaitTimeoutMs) }
                    },
                channelProfileUpdateSink = { result ->
                    sharedHomeStore?.accept(
                        SharedHomeIntent.ChannelProfileUpdated(
                            channelId = result.channelId,
                            name = result.name,
                            description = result.description
                        )
                    )
                },
                messageStore = sharedStores.threadMessageStore,
                cacheEnvironmentIdProvider = {
                    sharedStores.apiEnvironmentStore.current().apiBaseUrl
                },
                apiEnvironmentIdProvider = {
                    sharedStores.apiEnvironmentStore.current().apiBaseUrl
                },
                replyCacheIdentityAuthority = {
                    sharedStores.captureThreadReplyCacheIdentity(storeScope)
                },
                replyCacheIdentityTransitionWaiter = { transitionAnchor ->
                    sharedStores.awaitThreadReplyCacheIdentityTransition(storeScope, transitionAnchor)
                },
                canonicalConversationIdentityPublisher = { provenance, detail ->
                    sharedStores.publishCanonicalConversationIdentity(storeScope, provenance, detail)
                },
                payloadStore = sharedStores.threadPayloadStore,
                durableLastKnownReader = sharedStores.threadDurableLastKnownReader,
                enteredScopeSnapshotLoader = sharedStores.threadEnteredScopeSnapshotLoader,
                durablePageExtender = sharedStores.threadDurablePageExtender,
                durableAccessEvictor = sharedStores.threadDurableAccessEvictor,
                agentsApiClient = RaftAgentsApiClient(
                    transport = RaftAgentsNetworkApi(networkClient),
                    diagnosticsLogger = { message -> bridge.log("thread_agents_api $message") }
                ),
                actionCardsApiClient = RaftIntegrationsActionsPushApiClient(
                    RaftIntegrationsActionsPushNetworkApi(networkClient)
                ),
                savedStatusRepository =
                    RealSavedRepository(
                        sessionStore = authStore,
                        networkClient = networkClient,
                        warningLogger = { message -> bridge.log("thread_saved_repository $message") }
                    ),
                readReceiptCoordinator = sharedStores.processReadReceiptCoordinator(),
                readReceiptOwnerFactory = sharedStores::readReceiptOwner,
                threadPageSizeProvider = { serverId ->
                    sharedStores.serverFeatureFlags.snapshotFor(serverId).mobileThreadPageSize()
                },
                createAgentCoordinator = createAgentCoordinator,
                diagnosticsLogger = { message -> bridge.log("thread_api $message") }
            )
        }
    val tasksDataSource =
        remember {
            SharedTasksDataSource(
                api = NetworkRaftTasksApi(networkClient)
            )
        }
    val routerModule = remember(pager) {
        pager.acquireModule<RouterModule>(RouterModule.MODULE_NAME)
    }
    val unableToOpenThreadLabel = stringResource(MR.strings.thread_error_open_thread)
    val unableToOpenProfileLabel = stringResource(MR.strings.thread_error_open_profile)
    fun openStandaloneThreadPayload(
        nextPayload: RaftThreadScreenPayload,
        serverIdOverride: String? = null
    ) {
        val launchPayload = nextPayload.toWireThreadLaunchPayloadOrNull()
        if (launchPayload == null) {
            bridge.toast(unableToOpenThreadLabel)
            bridge.logWarn("thread_open_skip reason=missing_route_identity instanceId=${nextPayload.instanceId}")
            return
        }
        val targetStoreScope =
            RaftShellStoreScope.create(
                shellInstanceId = storeScope.shellInstanceId,
                initialServerId = threadParentNavigationServerId(serverIdOverride) ?: storeScope.initialServerId
            )
        val openPage = {
            val workspaceStore = sharedStores.adaptiveWorkspaceStore(storeScope)
            val source = adaptiveCloseRequest
            val session = workspaceStore.snapshot()
            val pane = session.workspace
            val desktopModeEnabled =
                KeyValueChatLayoutPreferenceStore(raftSharedPreferenceStore()).readDesktopModeOnLargeScreenSync()
            // task #36: an adaptive page is validated before any route, so a retired main/side
            // page opens nothing even after desktop mode turns off, the pane goes compact or the
            // server changes.
            val route = session.routeThreadOpen(source, desktopModeEnabled, targetStoreScope.initialServerId)
            if (route == AdaptiveThreadOpenRoute.Ignored) {
                bridge.logWarn("thread_open_skip reason=stale_adaptive_source")
            } else if (route == AdaptiveThreadOpenRoute.WithinDetail && source != null && pane != null) {
                // A reply under the shown channel opens in the side column when it fits;
                // otherwise the in-pane replace; a source retired meanwhile changes nothing.
                val next = workspaceStore.update { current ->
                    current.openWithinWideDetail(source, launchPayload, pane.serverId, desktopModeEnabled)
                }
                if (next.launchPayload != launchPayload && next.visibleSideThread()?.payload != launchPayload) {
                    bridge.toast(unableToOpenThreadLabel)
                    bridge.logWarn("thread_open_skip reason=stale_adaptive_source")
                }
            } else pager.openRaftPage(
                pageName = THREAD_PAGE,
                pageData = launchPayload.toThreadPageData(),
                storeScopeOverride = targetStoreScope,
                onMissingScope = {
                    bridge.toast(unableToOpenThreadLabel)
                    bridge.logWarn(
                        "thread_open_skip reason=missing_shell_scope instanceId=${nextPayload.instanceId}"
                    )
                }
            )
        }
        if (nextPayload.sourceThreadId?.isNotBlank() == true &&
            (nextPayload.originMessage != null || nextPayload.messages.isNotEmpty())
        ) {
            dataSource.cachePayload(
                nextPayload,
                ownerScopeId =
                    dataSource.replyCacheProvenanceState.value
                        ?.threadPayloadOwnerScopeId
                        .orEmpty()
            )
            openPage()
            return
        }
        openPage()
    }
    CompositionLocalProvider(
        LocalThreadAdaptiveInitiationCapture provides adaptiveInitiationCaptureHolder,
        LocalThreadAdaptiveNativeEditingReader provides adaptiveNativeEditingStateReader,
    ) {
    SharedThreadRouteContent(
        initialPayload = payload,
        timeContextProvider = liveTimeContextProvider,
        bridge = bridge,
        dataSource = dataSource,
        forwardTargetRepository = forwardTargetRepository,
        threadSendScope = sharedStores.threadSendScope,
        authStore = authStore,
        tasksDataSource = tasksDataSource,
        tasksDataStore = sharedStores.tasksDataStore,
        computersStore = computersStore,
        membersStore = membersStore,
        serverMembersStore = serverMembersStore,
        conversationIdentityProvider = sharedStores.conversationIdentityProvider(storeScope),
        storeScope = storeScope,
        composerDraftPersistSlice = sharedStores.composerDraftPersistSlice,
        eventBus = sharedStores.eventBus,
        active = pageVisible,
        adaptiveCloseRequest = adaptiveCloseRequest,
        onBack = {
            val closeRequest = adaptiveCloseRequest
            if (closeRequest != null) {
                sharedStores.eventBus.post(
                    eventName = RAFT_ADAPTIVE_DETAIL_CLOSE_EVENT,
                    eventData = closeRequest.toJson(),
                    crossProcess = true,
                    source = "adaptive_thread_root_back",
                )
            } else {
                routerModule.closePage()
            }
        },
        onOpenThreadPayload = { nextPayload -> openStandaloneThreadPayload(nextPayload) },
        onReplaceThreadPayload = {},
        onOpenParentThread = { currentPayload, currentSessionServerId ->
            val parentServerId = threadParentNavigationServerId(currentSessionServerId)
                ?: return@SharedThreadRouteContent false
            val request =
                currentPayload.resolveReplyParentConversationOpenRequest(
                    serverId = parentServerId,
                    conversationIdentityProvider = sharedStores.conversationIdentityProvider(storeScope)
                ) ?: return@SharedThreadRouteContent false
            val parentPayload =
                buildAppShellThreadPayload(
                    conversation = request.conversationIdentity,
                    timeContext = currentPayload.toRaftTimeCapabilities().staticContext(),
                    alignOwnMessagesRight = currentPayload.alignOwnMessagesRight,
                    compactConsecutiveMessages = currentPayload.compactConsecutiveMessages,
                    onWarn = bridge::logWarn
                ) ?: return@SharedThreadRouteContent false
            openStandaloneThreadPayload(parentPayload, serverIdOverride = parentServerId)
            true
        },
        onAuthRequired = { code ->
            bridge.logWarn("thread_auth_required code=$code route=standalone instanceId=${payload.instanceId}")
            if (!authLossReportInProgress) {
                authLossReportInProgress = true
                threadPageCoroutineScope.launch {
                    try {
                        val session =
                            runCatchingPreservingCancellation { authStore.readSession() }
                                .getOrNull()
                        val pendingOpenRequest =
                            payload
                                .toWireThreadLaunchPayloadOrNull()
                                ?.toAuthPendingOpenRequest(
                                    serverId = session?.currentServerId.orEmpty(),
                                    accountPrincipalId = session?.user?.id.orEmpty(),
                                )
                        sharedStores.authLossFunnel
                            .report(
                                AuthLossSignal(
                                    source = "thread:${payload.instanceId}",
                                    tokenFingerprint = session?.accessToken.authLossTokenFingerprint(),
                                    capturedSession = session,
                                    pendingOpenRequest = pendingOpenRequest
                                )
                            ).await()
                    } finally {
                        authLossReportInProgress = false
                    }
                }
            } else {
                bridge.logWarn(
                    "thread_auth_loss_report_skip reason=in_progress code=$code instanceId=${payload.instanceId}"
                )
            }
        },
        onOpenMemberProfile = { currentPayload, timelineSlice, identity ->
            val memberId = identity.memberId.value
            val authorProfile =
                timelineSlice.findThreadAuthorProfile(memberId)
                    ?: currentPayload.findThreadAuthorProfile(memberId)
            val selectedIdentity =
                identity.copy(
                    sourceServerId =
                        identity.sourceServerId
                            ?: authorProfile?.serverId
                            ?: currentPayload.members
                                .firstOrNull { it.id == memberId }
                                ?.sourceServerId
                                ?.takeIf { it.isNotBlank() }
                                ?.let(::ServerId)
                )
            val pageData = currentPayload.toThreadMemberDetailPageData(selectedIdentity)
            if (pageData == null) {
                bridge.toast(unableToOpenProfileLabel)
                bridge.logWarn(
                    "thread_member_profile_skip reason=missing_member memberId=$memberId " +
                    "instanceId=${currentPayload.instanceId}"
                )
            } else {
                authorProfile
                    ?.toThreadCandidateAgentDetailSnapshot()
                    ?.let { candidate ->
                        val agentDetailStore = RaftSharedStoreRegistry.get(bridge).agentDetailStore
                        agentDetailStore.dispatch(SharedAgentDetailIntent.SelectMember(candidate.agentId))
                        agentDetailStore.dispatch(
                            SharedAgentDetailIntent.SetDetail(
                                agentId = candidate.agentId,
                                detail = candidate,
                                serverId = selectedIdentity.sourceServerId
                            )
                        )
                    }
                pager.openRaftPage(
                    pageName = MEMBER_DETAIL_PAGE,
                    pageData = pageData,
                    onMissingScope = {
                        bridge.toast(unableToOpenProfileLabel)
                        bridge.logWarn(
                            "thread_member_profile_skip reason=missing_shell_scope memberId=$memberId " +
                                "instanceId=${currentPayload.instanceId}"
                        )
                    }
                )
            }
        },
        onOpenMembersPager = { currentPayload, serverId, channelId, currentStoreScope ->
            pager.openRaftPage(
                pageName = THREAD_MEMBERS_PAGE,
                pageData = currentPayload.toThreadMembersPageData(serverId, channelId),
                storeScopeOverride = currentStoreScope,
                authenticatedRouteAuthorityRequired = true,
            )
        },
        onOpenChannelSettings = { serverId, channelId, currentStoreScope ->
            pager.openRaftPage(
                pageName = CHANNEL_SETTINGS_PAGE,
                pageData = channelSettingsPageData(serverId, channelId),
                storeScopeOverride = currentStoreScope,
                authenticatedRouteAuthorityRequired = true,
            )
        }
    )
    }
}

@Composable
private fun ThreadMembersPageScreen() {
    val pager = LocalActivity.current.getPager() as Pager
    val bridge = Utils.bridgeModule(pager.pagerId)
    val route = remember(pager.pageData.params.toString()) { pager.pageData.params.toThreadMembersPageRouteOrNull() }
    if (route == null) {
        Box(modifier = Modifier.fillMaxSize().background(RaftColor.SurfaceWhite)) {
            Column(modifier = Modifier.fillMaxSize()) {
                RaftTopPageHeader(
                    title = "Members",
                    iconName = RaftLucideIconName.Users,
                    onBack = { pager.acquireModule<RouterModule>(RouterModule.MODULE_NAME).closePage() }
                )
                ThreadStateMessage(title = stringResource(MR.strings.common_error), detail = null)
            }
        }
        return
    }
    val storeScope = remember(pager.pageData.params.toString(), pager.pagerId) {
        pager.pageData.params.raftShellStoreScope(RaftShellStoreScope.Legacy.shellInstanceId)
    }
    val sharedStores = remember(bridge) { RaftSharedStoreRegistry.get(bridge) }
    val router = remember(pager) { pager.acquireModule<RouterModule>(RouterModule.MODULE_NAME) }
    val routeOwner =
        remember(pager.pageData.params.toString()) {
            pager.pageData.params.authenticatedRouteOwnerOrNull()
        }
    if (routeOwner == null || routeOwner.serverId != route.serverId.value) {
        Box(modifier = Modifier.fillMaxSize().background(RaftColor.SurfaceWhite)) {
            Column(modifier = Modifier.fillMaxSize()) {
                RaftTopPageHeader(
                    title = stringResource(MR.strings.thread_members_title, 0),
                    iconName = RaftLucideIconName.Users,
                    onBack = router::closePage,
                )
                ThreadStateMessage(title = stringResource(MR.strings.common_error), detail = null)
            }
        }
        return
    }
    val agentDetailStore = remember(sharedStores, storeScope) { sharedStores.agentDetailStore(storeScope) }
    val memberScope = rememberCoroutineScope()
    val authorityGateway = remember(sharedStores, storeScope) {
        sharedStores.authenticatedRouteAuthorityGateway(storeScope)
    }
    val serverMembersStore = remember(sharedStores, storeScope) { sharedStores.serverMembersStore(storeScope) }
    val liveOwner by
        remember(sharedStores, storeScope) {
            sharedStores.authenticatedRouteOwnerFlow(storeScope)
        }.collectAsState(sharedStores.currentAuthenticatedRouteOwner(storeScope))
    val initialChannelMembersSlice =
        remember(serverMembersStore, routeOwner, route.channelId) {
            serverMembersStore.currentChannelMemberSlice(routeOwner, route.channelId)
        }
    val channelMembersSlice by
        remember(serverMembersStore, routeOwner, route.channelId) {
            serverMembersStore.channelMemberSliceFlow(routeOwner, route.channelId)
        }.collectAsState(initialChannelMembersSlice)
    val initialServerMembersEntry =
        remember(serverMembersStore, routeOwner) {
            serverMembersStore.currentServerMembersEntry(routeOwner)
        }
    val serverMembersEntry by
        remember(serverMembersStore, routeOwner) {
            serverMembersStore.serverMembersEntryFlow(routeOwner)
        }.collectAsState(initialServerMembersEntry)
    val conversationIdentityProvider =
        remember(sharedStores, storeScope) { sharedStores.conversationIdentityProvider(storeScope) }
    val initialChannelProjection =
        remember(conversationIdentityProvider, route.serverId, route.channelId) {
            conversationIdentityProvider?.resolveProjection(route.serverId, route.channelId.value)
        }
    val channelProjections by
        remember(conversationIdentityProvider, route.serverId, route.channelId) {
            conversationIdentityProvider?.projectionFlow(route.serverId, listOf(route.channelId.value))
                ?: flowOf(emptyMap())
        }.collectAsState(
            initialChannelProjection?.let { mapOf(route.channelId.value to it) }.orEmpty()
        )

    fun refreshMembers() {
        if (liveOwner != routeOwner) return
        memberScope.launch {
            serverMembersStore.loadChannelMembers(
                owner = routeOwner,
                channelId = route.channelId,
                priority = DataRequestPriority.Visible,
                force = true
            )
            serverMembersStore.refreshMembers(
                owner = routeOwner,
                priority = DataRequestPriority.Background,
                force = false,
                reason = "thread_members_page"
            )
        }
    }

    LaunchedEffect(serverMembersStore, liveOwner, routeOwner, route.serverId, route.channelId) {
        if (liveOwner == routeOwner) refreshMembers()
    }
    val members = remember(channelMembersSlice.members, channelMembersSlice.canRemoveMembers, route.serverId) {
        channelMembersSlice.members
            .distinctBy { it.threadMemberKey }
            .map { it.toRaftThreadMemberItem(route.serverId).let { row ->
                row.copy(canRemove = row.canRemove && channelMembersSlice.canRemoveMembers)
            } }
    }
    val candidates = remember(serverMembersEntry.members, route.serverId, members) {
        threadAddMemberCandidatesExcludingJoined(
            candidates = serverMembersEntry.members.map { it.toRaftThreadMemberItem(route.serverId) },
            members = members,
            localServerId = route.serverId.value
        )
    }
    val agentStatusResolver = remember(serverMembersStore, route.serverId) {
        raftScopedAgentStatusResolver(serverMembersStore, route.serverId.value)
    }
    val memberAvatarResolver = remember(serverMembersStore, route.serverId) {
        raftMemberAvatarResolver(
            serverMembersStore = serverMembersStore,
            serverId = route.serverId.value,
            diagnosticsLogger = { message -> bridge.log("thread_members_pager_avatar $message") },
        )
    }
    var rosterQuery by remember(route) { mutableStateOf(TextFieldValue()) }
    var humansExpanded by remember(route) { mutableStateOf(true) }
    var agentsExpanded by remember(route) { mutableStateOf(true) }
    var externalExpanded by remember(route) { mutableStateOf(true) }
    val filteredMembers = filterThreadAddMemberCandidates(rosterQuery.text, members)
    val filteredExternal = channelMembersSlice.externalMembers.filter { member ->
        val query = rosterQuery.text.trim().removePrefix("@").lowercase()
        query.isBlank() || member.displayName.lowercase().contains(query) ||
            member.handles.any { it.lowercase().contains(query) }
    }
    var createAgentName by remember(routeOwner) { mutableStateOf<String?>(null) }
    var createAgentMode by remember(routeOwner) { mutableStateOf(MembersCreateAgentMode.Managed) }
    var canCreateAgents by remember(routeOwner) { mutableStateOf(false) }
    LaunchedEffect(liveOwner, routeOwner) {
        canCreateAgents = false
        if (liveOwner == routeOwner) {
            val session = sharedStores.authStore(storeScope).readSession()
            canCreateAgents = session?.servers?.firstOrNull { it.id == routeOwner.serverId }
                ?.toServerSummary()?.permissions?.canManageSettings == true
        } else createAgentName = null
    }
    var addDialogVisible by remember { mutableStateOf(false) }
    var addMemberStatus by remember { mutableStateOf("idle") }
    var addMemberErrorCode by remember { mutableStateOf<String?>(null) }
    var removalGate by
        remember(route.serverId, route.channelId) { mutableStateOf(ThreadMemberRemovalGateState()) }
    val unableToOpenProfileLabel = stringResource(MR.strings.thread_error_open_profile)
    val memberRemovedLabel = stringResource(MR.strings.thread_feedback_member_removed)
    val channelName =
        channelProjections[route.channelId.value]
            ?.title
            ?.trim()
            ?.removePrefix("#")
            ?.ifBlank { null }
            ?: route.channelId.value.trim().removePrefix("#")
    val authorityRejected = liveOwner != routeOwner
    val membersLoading =
        !authorityRejected &&
            members.isEmpty() &&
            channelMembersSlice.status in
                setOf(SharedServerMembersLoadStatus.Idle, SharedServerMembersLoadStatus.InFlight)
    val membersFailed =
        authorityRejected ||
            (members.isEmpty() && channelMembersSlice.status == SharedServerMembersLoadStatus.Error)
    val canAddMembers =
        !authorityRejected &&
            channelMembersSlice.canAddMembersKnown &&
            channelMembersSlice.canAddMembers
    var initialAddApplied by remember(route) { mutableStateOf(false) }
    LaunchedEffect(route.openAddMember, canAddMembers) {
        if (route.openAddMember && canAddMembers && !initialAddApplied) {
            initialAddApplied = true
            addDialogVisible = true
        }
    }

    LaunchedEffect(liveOwner, routeOwner) {
        if (liveOwner != routeOwner) {
            addDialogVisible = false
            addMemberStatus = "idle"
            addMemberErrorCode = null
            removalGate = ThreadMemberRemovalGateState()
        }
    }

    fun openMember(member: RaftThreadMemberItem) {
        val identity = member.memberDetailIdentity() ?: return
        val pageData = route.toMemberDetailPageData(identity) ?: return
        memberScope.launch {
            if (authorityGateway.capture(routeOwner) == null) {
                return@launch
            }
            member.toMemberProfile()
                ?.let { profile ->
                    agentDetailStore.dispatch(SharedAgentDetailIntent.SeedDetailFromMember(profile))
                }
            pager.openRaftPage(
                pageName = MEMBER_DETAIL_PAGE,
                pageData = pageData,
                onMissingScope = {
                    bridge.toast(unableToOpenProfileLabel)
                    bridge.logWarn(
                        "thread_member_profile_skip reason=missing_shell_scope memberId=${identity.memberId.value} " +
                            "instanceId=${route.instanceId}"
                    )
                }
            )
        }
    }

    /**
     * Opens the profile for an agent we already hold the id for (task #4). `openMember` needs a
     * row from the member list; a just-created agent may not be in the visible slice yet, so the
     * route data is built from the id directly.
     */
    fun openMemberProfile(memberId: MemberId, kind: MemberKind) {
        val identity = MemberDetailIdentity(memberId = memberId, kind = kind)
        val pageData = route.toMemberDetailPageData(identity)
        if (pageData == null) {
            // task #5: this used to `?: return` with no trace, so a broken route building
            // silently looked like "nothing happened" on device.
            bridge.logWarn(
                "thread_member_profile_skip reason=missing_route_data memberId=${memberId.value} " +
                    "instanceId=${route.instanceId}"
            )
            return
        }
        memberScope.launch {
            if (authorityGateway.capture(routeOwner) == null) {
                bridge.logWarn(
                    "thread_member_profile_skip reason=authority_lost memberId=${memberId.value} " +
                        "instanceId=${route.instanceId}"
                )
                return@launch
            }
            bridge.log(
                "thread_member_profile_open memberId=${memberId.value} kind=${kind.name} " +
                    "instanceId=${route.instanceId}"
            )
            pager.openRaftPage(
                pageName = MEMBER_DETAIL_PAGE,
                pageData = pageData,
                onMissingScope = {
                    bridge.toast(unableToOpenProfileLabel)
                    bridge.logWarn(
                        "thread_member_profile_skip reason=missing_shell_scope memberId=${memberId.value} " +
                            "instanceId=${route.instanceId}"
                    )
                }
            )
        }
    }

    fun requestRemoveMember(member: RaftThreadMemberItem) {
        if (authorityRejected || !channelMembersSlice.canRemoveMembers || !member.canRemove) return
        val confirmation =
            threadMemberRemovalConfirmation(
                member = member,
                serverId = route.serverId,
                channelId = route.channelId,
                channelName = channelName
            ) ?: return
        removalGate =
            reduceThreadMemberRemovalGate(
                state = removalGate,
                intent = ThreadMemberRemovalGateIntent.Request(confirmation)
            ).state
    }

    fun confirmRemoveMember() {
        val confirmed =
            reduceThreadMemberRemovalGate(
                state = removalGate,
                intent = ThreadMemberRemovalGateIntent.Confirm(route.serverId, route.channelId)
            )
        removalGate = confirmed.state
        val confirmation = confirmed.execute ?: return
        memberScope.launch {
            when (
                val result =
                    serverMembersStore.removeChannelMember(
                        owner = routeOwner,
                        request = confirmation.request,
                        priority = DataRequestPriority.Foreground
                    )
            ) {
                is DataResult.Content -> {
                    val applied = removalGate.inFlight
                    removalGate =
                        reduceThreadMemberRemovalGate(
                            state = removalGate,
                            intent = ThreadMemberRemovalGateIntent.CompleteSuccess(confirmation),
                        ).state
                    if (applied) bridge.toast(memberRemovedLabel)
                }
                is DataResult.NoPermission -> {
                    removalGate =
                        reduceThreadMemberRemovalGate(
                            state = removalGate,
                            intent =
                                ThreadMemberRemovalGateIntent.CompleteFailure(
                                    confirmation = confirmation,
                                    failure = ThreadMemberRemovalFailure.NoPermission,
                                    errorCode = result.blocker.code,
                                ),
                        ).state
                }
                is DataResult.Error -> {
                    removalGate =
                        reduceThreadMemberRemovalGate(
                            state = removalGate,
                            intent =
                                ThreadMemberRemovalGateIntent.CompleteFailure(
                                    confirmation = confirmation,
                                    failure = ThreadMemberRemovalFailure.Failed,
                                    errorCode = result.error.code,
                                ),
                        ).state
                }
                is DataResult.Empty -> {
                    removalGate =
                        reduceThreadMemberRemovalGate(
                            state = removalGate,
                            intent =
                                ThreadMemberRemovalGateIntent.CompleteFailure(
                                    confirmation = confirmation,
                                    failure = ThreadMemberRemovalFailure.Failed,
                                    errorCode = result.reason.name,
                                ),
                        ).state
                }
            }
        }
    }

    Box(modifier = Modifier.fillMaxSize().background(RaftColor.SurfaceWhite)) {
        ThreadMembersPageContent(
            members = members, filteredMembers = filteredMembers, filteredExternal = filteredExternal,
            externalMemberCount = channelMembersSlice.externalMembers.size, candidates = candidates,
            rosterQuery = rosterQuery, onQueryChange = { rosterQuery = it },
            agentsExpanded = agentsExpanded, humansExpanded = humansExpanded, externalExpanded = externalExpanded,
            onAgentsExpandedChange = { agentsExpanded = it }, onHumansExpandedChange = { humansExpanded = it },
            onExternalExpandedChange = { externalExpanded = it },
            addDialogVisible = addDialogVisible, onAddVisibleChange = { addDialogVisible = it },
            addMemberStatus = addMemberStatus, addMemberErrorCode = addMemberErrorCode, removalGate = removalGate,
            membersFailed = membersFailed, membersLoading = membersLoading,
            refreshing = channelMembersSlice.status == SharedServerMembersLoadStatus.InFlight && members.isNotEmpty(),
            canAddMembers = canAddMembers, agentStatusResolver = agentStatusResolver, memberAvatarResolver = memberAvatarResolver,
            onBack = { router.closePage() }, onRefresh = ::refreshMembers,
            onOpenMember = ::openMember, onRemoveMember = ::requestRemoveMember,
            canCreateAgents = canCreateAgents,
            localServerId = route.serverId.value,
            onCreateAgent = { name, mode ->
                if (canCreateAgents && liveOwner == routeOwner) {
                    createAgentName = name
                    createAgentMode = mode
                }
            },
            onSubmit = { selectedMembers ->
                val profiles = selectedMembers.mapNotNull { it.toMemberProfile() }
                if (profiles.isEmpty() || profiles.size != selectedMembers.size) return@ThreadMembersPageContent
                if (addMemberStatus == "adding") return@ThreadMembersPageContent
                addMemberStatus = "adding"
                addMemberErrorCode = null
                memberScope.launch {
                    when (
                        val result =
                            serverMembersStore.addChannelMembersBatch(
                                owner = routeOwner,
                                request =
                                    build.raft.app.data.AddChannelMembersBatchRequest(
                                        channelId = route.channelId,
                                        userIds = profiles.filter { it.kind != MemberKind.Agent }.map { it.id },
                                        agentIds = profiles.filter { it.kind == MemberKind.Agent }.map { it.id }
                                    ),
                                priority = DataRequestPriority.Foreground
                            )
                    ) {
                        is DataResult.Content -> {
                            addMemberStatus = "idle"
                            addMemberErrorCode = null
                            addDialogVisible = false
                        }
                        is DataResult.NoPermission -> {
                            addMemberStatus = "no_permission"
                            addMemberErrorCode = result.blocker.code
                        }
                        is DataResult.Error -> {
                            addMemberStatus = "failed"
                            addMemberErrorCode = result.error.code
                        }
                        is DataResult.Empty -> {
                            addMemberStatus = "failed"
                            addMemberErrorCode = result.reason.name
                        }
                    }
                }
            }
        )
        RaftBackHandler(enabled = addDialogVisible, label = "thread_members_inline_add") {
            if (addMemberStatus != "adding") addDialogVisible = false
        }
        createAgentName?.let { initialName ->
            ChannelMembersCreateAgentDialog(
                owner = routeOwner, channelId = route.channelId, initialName = initialName, mode = createAgentMode,
                authority = authorityGateway, computersStore = sharedStores.computersStore(storeScope),
                formStore = sharedStores.createAgentFormStore(storeScope), membersStore = serverMembersStore,
                onDismiss = { createAgentName = null; refreshMembers() },
                onJoined = { createAgentName = null; addDialogVisible = false; refreshMembers() },
                // task #4 (Hands 1c6885d8): a freshly created external agent is useless until
                // it is configured, so land the user on its profile instead of dropping them
                // back into the member list. Managed agents keep the existing behaviour.
                onCreated = { memberId ->
                    if (createAgentMode == MembersCreateAgentMode.External) {
                        openMemberProfile(memberId, MemberKind.Agent)
                    }
                },
            )
        }
        removalGate.pending?.let { confirmation ->
            ThreadRemoveMemberConfirmationDialog(
                confirmation = confirmation,
                removing = removalGate.inFlight,
                errorMessage =
                    when (removalGate.failure) {
                        ThreadMemberRemovalFailure.NoPermission ->
                            stringResource(MR.strings.thread_members_remove_no_permission)
                        ThreadMemberRemovalFailure.Failed -> stringResource(MR.strings.thread_members_remove_failed)
                        else -> null
                    },
                onDismiss = {
                    removalGate =
                        reduceThreadMemberRemovalGate(
                            state = removalGate,
                            intent = ThreadMemberRemovalGateIntent.Dismiss
                        ).state
                },
                onConfirm = ::confirmRemoveMember
            )
        }
    }
}






/** The production roster renderer; visual fixtures supply typed state without route payloads. */
@Composable
internal fun ThreadMembersPageContent(
    members: List<RaftThreadMemberItem>,
    filteredMembers: List<RaftThreadMemberItem>,
    filteredExternal: List<build.raft.app.model.ChannelExternalMemberProfile>,
    externalMemberCount: Int,
    candidates: List<RaftThreadMemberItem>,
    rosterQuery: TextFieldValue,
    onQueryChange: (TextFieldValue) -> Unit,
    agentsExpanded: Boolean,
    humansExpanded: Boolean,
    externalExpanded: Boolean,
    onAgentsExpandedChange: (Boolean) -> Unit,
    onHumansExpandedChange: (Boolean) -> Unit,
    onExternalExpandedChange: (Boolean) -> Unit,
    addDialogVisible: Boolean,
    onAddVisibleChange: (Boolean) -> Unit,
    addMemberStatus: String,
    addMemberErrorCode: String?,
    removalGate: ThreadMemberRemovalGateState,
    membersFailed: Boolean,
    membersLoading: Boolean,
    refreshing: Boolean,
    canAddMembers: Boolean,
    agentStatusResolver: RaftAgentStatusResolver,
    memberAvatarResolver: RaftMemberAvatarResolver,
    onBack: () -> Unit,
    onRefresh: () -> Unit,
    onOpenMember: (RaftThreadMemberItem) -> Unit,
    onRemoveMember: (RaftThreadMemberItem) -> Unit,
    onSubmit: (List<RaftThreadMemberItem>) -> Unit,
    canCreateAgents: Boolean = false,
    onCreateAgent: (String, MembersCreateAgentMode) -> Unit = { _, _ -> },
    localServerId: String? = null,
) {
    val rosterListState = rememberLazyListState()
    // task #175: the page draws under the system navigation bar; whichever
    // element sits last (the Add Member bar, else the roster) keeps clear of it.
    val bottomSafeArea = raftBottomSafeAreaPadding()
    // Web ChannelMembers presentation="page" (ChannelMembers.tsx, ChannelMemberList.tsx), drawn
    // with compose/designsystem parts (ChannelMembersPage.kt).
    RaftDesignSystemTheme {
    Column(modifier = Modifier.fillMaxSize().background(RaftTheme.colors.layerCanvas)) {
        ChannelMembersPageHeader(
            title = stringResource(if (addDialogVisible) MR.strings.thread_action_add_member else MR.strings.thread_members_heading),
            count = (members.size + externalMemberCount).takeIf { !addDialogVisible && !membersLoading },
            refreshing = refreshing,
            onBack = {
                if (addDialogVisible) {
                    if (addMemberStatus != "adding") onAddVisibleChange(false)
                } else onBack()
            },
        )
        if (addDialogVisible && canAddMembers) {
            ThreadAddMemberModal(
                inline = true, members = members, candidates = candidates,
                localServerId = localServerId,
                canAddMembers = canAddMembers, agentStatusResolver = agentStatusResolver,
                memberAvatarResolver = memberAvatarResolver, addMemberStatus = addMemberStatus,
                addMemberErrorCode = addMemberErrorCode,
                onDismiss = { onAddVisibleChange(false) },
                onSubmit = { onSubmit(listOf(it)) }, onSubmitBatch = onSubmit,
                canCreateAgents = canCreateAgents, onCreateAgent = onCreateAgent,
            )
        } else {
        ChannelMembersSearchBar(query = rosterQuery, onQueryChange = onQueryChange)
        if (removalGate.failure != null) {
            ChannelMembersWarning(
                if (removalGate.failure == ThreadMemberRemovalFailure.NoPermission) {
                    stringResource(MR.strings.thread_members_remove_no_permission)
                } else {
                    stringResource(MR.strings.thread_members_remove_failed)
                }
            )
        }
        LazyColumn(
            state = rosterListState,
            modifier = Modifier.weight(1f).fillMaxWidth(),
            contentPadding = PaddingValues(bottom = 12.dp + if (canAddMembers && !membersLoading) 0.dp else bottomSafeArea),
        ) {
            if (membersFailed) {
                item {
                    ChannelMembersEmptyState(
                        icon = RaftLucideIconName.TriangleAlert,
                        title = stringResource(MR.strings.common_error),
                        actionLabel = stringResource(MR.strings.common_retry),
                        onAction = onRefresh,
                    )
                }
            } else if (membersLoading) {
                item { ChannelMembersLoading() }
            } else if (filteredMembers.isEmpty() && filteredExternal.isEmpty()) {
                item {
                    val query = rosterQuery.text.trim()
                    if (query.isNotEmpty() && (members.isNotEmpty() || externalMemberCount > 0)) {
                        ChannelMembersEmptyState(
                            icon = RaftLucideIconName.Search,
                            title = stringResource(MR.strings.thread_members_no_matches, query),
                        )
                    } else {
                        ChannelMembersEmptyState(
                            icon = RaftLucideIconName.Users,
                            title = stringResource(MR.strings.thread_members_empty),
                        )
                    }
                }
            } else {
                val agents = filteredMembers.filter { it.kind.equals("agent", ignoreCase = true) }
                val humans = filteredMembers.filterNot { it.kind.equals("agent", ignoreCase = true) }
                // Humans first, then agents, then bridge participants (web member page order).
                if (humans.isNotEmpty()) {
                    item(key = "section:humans") {
                        RaftSidebarSectionHeader(
                            title = stringResource(MR.strings.thread_members_humans), count = humans.size,
                            expanded = humansExpanded, onExpandedChange = onHumansExpandedChange,
                            countSeparator = " · ",
                        )
                    }
                    if (humansExpanded) items(humans.size, key = { humans[it].memberKey }) { index ->
                        ThreadMembersPagerRow(
                            member = humans[index],
                            divider = index > 0,
                            agentStatusResolver = agentStatusResolver,
                            memberAvatarResolver = memberAvatarResolver,
                            removing = removalGate.inFlight && removalGate.pending?.memberRowId == humans[index].id,
                            onOpen = onOpenMember,
                            onRemove = onRemoveMember
                        )
                    }
                }
                if (agents.isNotEmpty()) {
                    item(key = "section:agents") {
                        RaftSidebarSectionHeader(
                            title = stringResource(MR.strings.thread_members_agents), count = agents.size,
                            expanded = agentsExpanded, onExpandedChange = onAgentsExpandedChange,
                            countSeparator = " · ",
                        )
                    }
                    if (agentsExpanded) items(agents.size, key = { agents[it].memberKey }) { index ->
                        ThreadMembersPagerRow(
                            member = agents[index],
                            divider = index > 0,
                            agentStatusResolver = agentStatusResolver,
                            memberAvatarResolver = memberAvatarResolver,
                            removing = removalGate.inFlight && removalGate.pending?.memberRowId == agents[index].id,
                            onOpen = onOpenMember,
                            onRemove = onRemoveMember
                        )
                    }
                }
                if (filteredExternal.isNotEmpty()) {
                    item(key = "section:external") {
                        RaftSidebarSectionHeader(
                            title = stringResource(MR.strings.thread_members_external), count = filteredExternal.size,
                            expanded = externalExpanded, onExpandedChange = onExternalExpandedChange,
                            countSeparator = " · ",
                        )
                    }
                    if (externalExpanded) items(filteredExternal.size, key = { "external:${filteredExternal[it].id}" }) { index ->
                        val member = filteredExternal[index]
                        // SSOT audit: the live time context (as rememberRaftAgentStatusIndicatorState
                        // reads it), so the lime/cyan boundary moves on its minute tick.
                        val now = LocalRaftTimeContextProvider.current?.current?.nowEpochMillis ?: defaultNowMillis()
                        val handlesLine = member.handles.joinToString(" · ") { "@${it.removePrefix("@")}" }
                        ChannelMembersRow(
                            title = member.displayName,
                            subtitle = handlesLine,
                            avatarWireValue = member.avatarUrl, avatarLabel = member.avatarLabel,
                            avatarFill = RaftColor.AccentLavender,
                            cacheSubject = null, cacheServerId = null,
                            statusColor = member.lastSeenAt?.let { seen ->
                                if (isExternalAgentSeenOnline(seen, now)) RaftColor.AccentLime else RaftColor.AccentCyan
                            },
                            statusPulsing = false,
                            badges = listOfNotNull(
                                member.provider?.takeIf { it.isNotBlank() }?.let { ChannelMemberBadge(it, ChannelMemberBadgeKind.Provider) }
                            ),
                            divider = index > 0,
                            // A long press copies the handle line as shown ("@a", "@a · @b").
                            subtitleCopyText = handlesLine,
                        )
                    }
                }
            }
        }
        // Web: hidden while the roster loads, disabled when nobody is left to add.
        if (canAddMembers && !membersLoading) {
            ChannelMembersAddBar(
                enabled = addMemberStatus != "adding" && candidates.isNotEmpty(),
                bottomSafeArea = bottomSafeArea,
                onClick = { onAddVisibleChange(!addDialogVisible) },
            )
        }
        }
    }
    }
}

@Composable
internal fun ThreadHeaderVisualScreen() {
    val payload = remember {
        RaftThreadScreenPayload(
            instanceId = "visual-thread-header",
            // The web case renders ChatPanel for the `channel-home` channel, whose header carries
            // Search ("Search this channel") beside Settings.
            sourceThreadId = "channel-home",
            title = "#首页专修",
            subtitle = "Home shell, server badge, and bottom dock polish",
            status = "content",
            surfaceKind = RaftThreadSurfaceKind.Channel,
            selectedTab = "chat",
            showModeTabs = true,
            showSettingsAction = true,
            showMembersAction = true,
            membersCount = 4,
            showOpenInChannelAction = false
        )
    }
    // React's thread-header element includes the Chat/Tasks/Files mode-tab strip
    // that the real page renders via RaftTabbedScaffold directly below
    // ThreadPageHeader, so the fixture renders the same RaftTopTabBar row with
    // the thread tab specs (Chat selected). The explicit 120dp canvas matches the
    // react element height (1170x360px @3x = 390x120dp); the header+tabs measure
    // 62+32=94dp, so the white slack at the bottom exposes the real height delta
    // (task #370).
    Column(modifier = Modifier.width(390.dp).height(120.dp).background(RaftColor.SurfaceWhite)) {
        ThreadPageHeader(
            payload = payload,
            applyTopSafeArea = false,
            onBack = {},
            onOpenInChannel = {},
            onOpenMemberProfile = {},
            onOpenSearch = {},
            onShowMembers = {},
            onShowSettings = {}
        )
        RaftTopTabBar(
            items = RaftThreadTab.entries.map { it.toRaftTabSpec().toTopTabBarItem() },
            selectedKey = RaftThreadTab.Chat.toString(),
            onSelectedKeyChange = {},
            itemKeyPrefix = "thread-tab"
        )
    }
}

@Composable
internal fun Task797ThreadHeaderVisualScreen() {
    val pager = LocalActivity.current.getPager() as Pager
    val applyTopSafeArea = pager.pageData.params.optBoolean("task797IncludeTopSafeArea", false)
    val agentIdentity =
        remember {
            MemberDetailIdentity(
                memberId = MemberId("agent-task797-pixel"),
                kind = MemberKind.Agent,
                sourceServerId = ServerId("server-task797"),
            )
        }
    val payload =
        remember(agentIdentity) {
            RaftThreadScreenPayload(
                instanceId = "task797-thread-header-evidence",
                title = "Pixel visual verification for the unified secondary page header",
                subtitle = "Working - measuring safe-area alignment and action centerlines",
                status = "content",
                surfaceKind = RaftThreadSurfaceKind.DirectMessage,
                streamChannelId = "dm-task797-pixel",
                selectedTab = "chat",
                showModeTabs = false,
                showSettingsAction = false,
                showMembersAction = false,
                showOpenInChannelAction = false,
                dmPeerIdentity = agentIdentity,
                dmPeerName = "Pixel visual verification",
                dmPeerAvatarLabel = "PX",
                activityMuted = false,
                activityMuteSupported = true,
            )
        }
    val headerDisplay =
