private val ThreadInlineMetaTagHorizontalPadding: Dp = 10.dp

@Composable
private fun ThreadMessageCommentRefChip(
    ref: RaftThreadMessageCommentRef,
    enabled: Boolean,
    modifier: Modifier = Modifier,
    onOpen: () -> Unit
) {
    val label =
        buildString {
            append("re: ")
            append(ref.filename)
            ref.anchorLabel?.takeIf { it.isNotBlank() }?.let { anchor ->
                append(" · ")
                append(anchor)
            }
        }
    Row(
        modifier =
            modifier
                .then(if (enabled) Modifier.clickable(onClick = onOpen) else Modifier)
                // raft reference chip: fill-muted on the chip radius with a hairline.
                .raftControlSurface(
                    fill = RaftColor.FillMuted.copy(alpha = if (enabled) 1f else 0.7f),
                    border = RaftColor.BorderHairline,
                    radius = RaftAppRadius.Chip,
                    borderWidth = RaftAppStroke.Thin
                )
                .padding(horizontal = RaftAppSpacing.Xs, vertical = 4.dp),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(5.dp)
    ) {
        RaftLucideIcon(
            RaftLucideIconName.MessageSquare,
            modifier = Modifier.size(12.dp),
            color = if (enabled) "#FF111827" else "#FF6B7280"
        )
        Text(
            text = label,
            style =
                RaftType.Caption.withRaftFontWeight(FontWeight.Bold).copy(
                    color = if (enabled) RaftColor.TextBlack else RaftColor.TextMutedGray
                ),
            color = if (enabled) RaftColor.TextBlack else RaftColor.TextMutedGray,
            maxLines = 1,
            overflow = TextOverflow.Ellipsis,
            modifier = Modifier.weight(1f)
        )
    }
}

internal fun RaftThreadAttachmentItem.isImageAttachment(): Boolean =
    raftFilePreviewIsImageAttachment(fileName = name, mimeType = mimeType)

private fun RaftThreadAttachmentItem.normalizedMimeType(): String =
    mimeType.substringBefore(';').trim().lowercase()

internal fun RaftThreadAttachmentItem.isMarkdownAttachment(): Boolean =
    raftFilePreviewIsMarkdownAttachment(fileName = name, mimeType = mimeType)

internal fun RaftThreadAttachmentItem.isTextLikeAttachment(): Boolean =
    !isMarkdownAttachment() && raftFilePreviewIsTextLikeAttachment(fileName = name, mimeType = mimeType)

internal fun RaftThreadAttachmentItem.isPreviewableAudioAttachment(): Boolean =
    raftFilePreviewIsAudioAttachment(fileName = name, mimeType = mimeType)

internal fun RaftThreadAttachmentItem.isPreviewableVideoAttachment(): Boolean =
    raftFilePreviewIsPreviewableVideoAttachment(fileName = name, mimeType = mimeType)

internal fun RaftThreadAttachmentItem.isHtmlAttachment(): Boolean =
    normalizedMimeType() == "text/html" || name.endsWith(".html", ignoreCase = true) || name.endsWith(".htm", ignoreCase = true)

internal fun RaftThreadAttachmentItem.genericAttachmentMetaLine(): String =
    displaySizeLabel()

private fun RaftThreadAttachmentItem.threadAttachmentDownloadId(generation: Long): String =
    listOf("attempt-$generation", "thread_attachment", id.ifBlank { name.ifBlank { "attachment" } }, name.ifBlank { "attachment" })
        .joinToString(":")
        .filter { it.isLetterOrDigit() || it == '-' || it == '_' || it == ':' || it == '.' }
        .take(160)
        .ifBlank { "thread-attachment-download" }

internal fun RaftThreadAttachmentItem.threadAttachmentChipMetaLine(htmlPreviewLabel: String): String =
    listOf(
        htmlPreviewLabel.takeIf { isHtmlAttachment() },
        displaySizeLabel()
    )
        .filterNotNull()
        .filter { it.isNotBlank() }
        .joinToString(" · ")

private fun RaftThreadAttachmentItem.threadAttachmentRendersAsCard(): Boolean =
    !isPreviewableVideoAttachment() && !isPreviewableAudioAttachment()

/** Consecutive file cards share one wrapping group; each inline player stands alone, in order. */
private fun List<RaftThreadAttachmentItem>.threadAttachmentCardRuns(): List<List<RaftThreadAttachmentItem>> {
    val runs = mutableListOf<MutableList<RaftThreadAttachmentItem>>()
    forEach { attachment ->
        val last = runs.lastOrNull()
        if (attachment.threadAttachmentRendersAsCard() && last != null && last.first().threadAttachmentRendersAsCard()) {
            last += attachment
        } else {
            runs += mutableListOf(attachment)
        }
    }
    return runs
}

private fun ThreadAttachmentOpenUiState?.threadAttachmentOpenFailed(): Boolean =
    this?.status in setOf("missing", "no_app", "storage_failed", "download_failed", "failed")

// raft-ui MessageAttachmentGroup `max-w-[360px]`.
private val ThreadAttachmentGroupMaxWidth = 360.dp

/** UI-bound formatting: raw bytes win; sizeLabel exists only for compatibility snapshots. */
internal fun RaftThreadAttachmentItem.displaySizeLabel(): String =
    sizeBytes.takeIf { it > 0L }?.let(::formatAttachmentSizeLabel) ?: sizeLabel

/** Group identity for the initial Thread image editor's N/N event stream. */
internal fun threadComposerImageAnnotationGroupId(actionId: String, fileCount: Int): String =
    actionId.trim().takeIf { it.isNotBlank() && fileCount > 1 }?.let { "$it-group" }.orEmpty()

/**
 * Builds the production initial-picker preview payload. Keeping this construction
 * in a pure helper makes the group identity and the gallery cardinality directly
 * testable without mounting a pager or an event bus.
 */
internal fun threadComposerImageAnnotationPayload(
    threadInstanceKey: String,
    actionId: String,
    files: List<PlatformFile>,
    originalImage: Boolean,
): RaftFilePreviewPayload? {
    val firstFile = files.firstOrNull() ?: return null
    val previewUri = firstFile.composerLocalPreviewUri().orEmpty()
    return RaftFilePreviewPayload(
        kind = "image",
        title = "Image preview",
        subtitle = firstFile.fileName,
        name = firstFile.fileName,
        path = firstFile.fileName,
        meta =
            listOf(
                firstFile.sizeBytes?.let(::formatAttachmentSizeLabel).orEmpty(),
                firstFile.mimeType.orEmpty()
            ).filter { it.isNotBlank() }.joinToString(" · "),
        imageUrl = previewUri.takeIf { it.isNotBlank() },
        message = if (previewUri.isBlank()) "Image preview is unavailable." else "",
        externalFileName = firstFile.fileName,
        externalMimeType = firstFile.mimeType.orEmpty(),
        imageGallery = files.map { file -> file.toComposerImageGalleryImage() },
        composerImageThreadKey = threadInstanceKey,
        composerImageActionId = actionId,
        composerImageGroupId = threadComposerImageAnnotationGroupId(actionId, files.size),
        composerImageFileRef = firstFile.fileRef.orEmpty(),
        composerImageFileName = firstFile.fileName,
        composerImageMimeType = firstFile.mimeType.orEmpty(),
        composerImageSizeBytes = firstFile.sizeBytes,
        composerImagePreviewUri = previewUri,
        composerImageCompressAfterEdit = !originalImage,
        composerImageOriginalOptionEnabled = true,
        composerImageOwnedTemporaryFileRefs =
            files.filter(PlatformFile::isComposerImageOwnedTemporary)
                .mapNotNull(PlatformFile::fileRef),
        composerImageCanComplete = true,
        composerImageCanEdit = true
    )
}

private fun RaftThreadAttachmentItem.toThreadAttachmentPreviewPayload(
    kind: String,
    title: String,
    content: String = "",
    imageUrl: String? = null,
    message: String = "",
    error: String? = null,
    externalUrl: String? = null
): RaftFilePreviewPayload =
    RaftFilePreviewPayload(
        kind = kind,
        requestedKind = kind,
        title = title,
        subtitle = name.ifBlank { "Attachment" },
        name = name.ifBlank { "Attachment" },
        path = name,
        meta = genericAttachmentMetaLine(),
        content = content,
        markdown = kind == "markdown",
        imageUrl = imageUrl,
        message = message,
        messageDesc = null,
        error = error,
        externalUrl = externalUrl,
        externalFileName = name.ifBlank { "attachment-${id.take(8)}" },
        externalMimeType = mimeType
    )

/** Renderer-facing URI; [PlatformFile.fileRef] remains the platform upload handle. */
internal fun PlatformFile.composerLocalPreviewUri(): String? =
    previewUri?.takeIf { it.isNotBlank() }
        ?: fileRef?.takeIf { it.isNotBlank() }

/**
 * Rehydrate a persisted composer attachment into the platform-file descriptor used by the
 * editable preview.  The preview URI and upload handle are deliberately kept as separate fields:
 * a remote/local thumbnail must never be promoted to a fileRef merely because it is renderable.
 */
internal fun SharedThreadComposerAttachment.toComposerImagePlatformFile(): PlatformFile =
    PlatformFile(
        id = id,
        fileName = fileName,
        mimeType = mimeType,
        sizeBytes = sizeBytes.takeIf { it > 0L },
        previewUri = previewUri?.trim()?.takeIf { it.isNotBlank() }
            ?: fileRef?.trim()?.takeIf { it.isNotBlank() },
        fileRef = fileRef?.trim()?.takeIf { it.isNotBlank() },
        source = source.orEmpty()
    )

/**
 * Rehydrate only a still-sendable local draft row into the platform-file descriptor used by the
 * upload/retry path. Durable draft rows may also contain server-owned ready attachments and
 * render-only projections; those are deliberately not promoted to a local upload handle.
 *
 * `previewUri` is presentation-only. A remote thumbnail must never be copied into
 * [PlatformFile.fileRef] just because it is non-empty. The original source and fileRef are kept
 * (apart from surrounding whitespace) so a process-restored retry uses the same provider handle
 * that was persisted by the owning picker/editor bridge.
 */
internal fun SharedThreadComposerAttachment.toRestoredThreadComposerPlatformFile(): PlatformFile? {
    val normalizedStatus = status.trim().lowercase()
    if (normalizedStatus !in setOf("queued", "uploading", "failed")) return null

    val normalizedId = id.trim().takeIf { it.isNotBlank() } ?: return null
    val normalizedRef = fileRef?.trim()?.takeIf { it.isNotBlank() } ?: return null
    val normalizedSource = source?.trim()?.takeIf { it.isNotBlank() } ?: return null
    if (
        normalizedSource != "external_share" &&
            normalizedSource !in ThreadComposerOwnedTemporarySources
    ) {
        return null
    }

    val normalizedName = fileName.trim().takeIf { it.isNotBlank() } ?: return null
    val normalizedPreview = previewUri?.trim()?.takeIf { it.isNotBlank() }
    val normalizedMime = mimeType?.trim()?.takeIf { it.isNotBlank() }
    return PlatformFile(
        id = normalizedId,
        fileName = normalizedName,
        mimeType = normalizedMime,
        sizeBytes = sizeBytes.takeIf { it > 0L },
        previewUri = normalizedPreview,
        fileRef = normalizedRef,
        source = normalizedSource
    )
}

internal fun PlatformFile.toComposerImageGalleryImage(): RaftFilePreviewGalleryImage =
    RaftFilePreviewGalleryImage(
        attachmentId = id,
        name = fileName,
        mimeType = mimeType.orEmpty(),
        sizeLabel = sizeBytes?.let(::formatAttachmentSizeLabel).orEmpty(),
        thumbnailUrl = composerLocalPreviewUri(),
        composerImageFileRef = fileRef.orEmpty(),
        composerImagePreviewUri = composerLocalPreviewUri().orEmpty(),
        composerImageSizeBytes = sizeBytes,
        composerImageOwnedTemporary = isComposerImageOwnedTemporary()
    )

internal fun PlatformFile.isComposerImageOwnedTemporary(): Boolean {
    if (fileRef.isNullOrBlank() || source !in ThreadComposerOwnedTemporarySources) return false
    val normalizedMime = mimeType.orEmpty().substringBefore(';').trim().lowercase()
    val hasVideoExtension =
        sequenceOf(fileName, fileRef.orEmpty()).any { candidate ->
            val extension =
                candidate
                    .substringBefore('?')
                    .substringBefore('#')
                    .substringAfterLast('.', missingDelimiterValue = "")
                    .lowercase()
            extension in RaftFilePreviewVideoExtensions
        }
    return !normalizedMime.startsWith("video/") && !hasVideoExtension
}

@Composable
private fun ThreadMessageAttachments(
    attachments: List<RaftThreadAttachmentItem>,
    alignEnd: Boolean,
    attachmentOpenStates: Map<String, ThreadAttachmentOpenUiState> = emptyMap(),
    onOpenAttachment: (String) -> Unit,
    onDownloadAttachment: (String) -> Unit = {}
) {
    if (attachments.isEmpty()) return

    val imageAttachments = remember(attachments) { attachments.filter { it.isImageAttachment() } }
    val fileAttachments = remember(attachments) { attachments.filterNot { it.isImageAttachment() } }

    Column(
        modifier = Modifier.fillMaxWidth(),
        verticalArrangement = Arrangement.spacedBy(RaftAppSpacing.Sm),
        horizontalAlignment = if (alignEnd) Alignment.End else Alignment.Start
    ) {
        if (imageAttachments.isNotEmpty()) {
            val imageDimensions =
                remember(imageAttachments) {
                    imageAttachments.map { RaftMessageImageDimensions(width = it.width, height = it.height) }
                }
            // raft-ui MessageImageGallery (web MessageItem): rounded hairline frames on fill-muted,
            // a lone image in its own reserved box, multi-image rows in the phone grid.
            CompositionLocalProvider(
                LocalRaftColors provides
                    if (RaftAppThemeState.isDark) {
                        build.raft.designsystem.tokens.RaftUiThemeColors.RaftDark
                    } else {
                        build.raft.designsystem.tokens.RaftUiThemeColors.RaftLight // raft-color: light branch of the theme switch
                    }
            ) {
                RaftMessageImageGallery(
                    images = imageDimensions,
                    onClick = { index -> onOpenAttachment(imageAttachments[index].id) }
                ) { layout ->
                    ThreadImageAttachmentContent(
                        attachment = imageAttachments[layout.index],
                        fit = layout.fit
                    )
                }
            }
        }
        // raft-ui MessageAttachmentGroup: file cards wrap side by side (`flex flex-wrap gap-2`,
        // at most 360 wide); inline video / audio players keep their own full-width rows.
        val fileAttachmentRuns =
            remember(fileAttachments) { fileAttachments.threadAttachmentCardRuns() }
        fileAttachmentRuns.forEach { run ->
            val first = run.first()
            if (!first.threadAttachmentRendersAsCard()) {
                ThreadAttachmentChip(
                    attachment = first,
                    openState = attachmentOpenStates[first.id],
                    onOpen = { onOpenAttachment(first.id) },
                    onDownload = { onDownloadAttachment(first.id) }
                )
            } else {
                @OptIn(ExperimentalLayoutApi::class)
                FlowRow(
                    modifier = Modifier.widthIn(max = ThreadAttachmentGroupMaxWidth),
                    horizontalArrangement =
                        Arrangement.spacedBy(RaftAppSpacing.Sm, if (alignEnd) Alignment.End else Alignment.Start),
                    verticalArrangement = Arrangement.spacedBy(RaftAppSpacing.Sm)
                ) {
                    run.forEach { attachment ->
                        ThreadAttachmentChip(
                            attachment = attachment,
                            openState = attachmentOpenStates[attachment.id],
                            onOpen = { onOpenAttachment(attachment.id) },
                            onDownload = { onDownloadAttachment(attachment.id) }
                        )
                    }
                }
            }
        }
    }
}

@Composable
private fun ThreadImageAttachmentContent(
    attachment: RaftThreadAttachmentItem,
    fit: RaftMessageImageFit
) {
    val fallbackHost = LocalThreadInlineImageFallbackHost.current
    val fallbackUrl = fallbackHost?.state?.resolvedUrls?.get(attachment.id)
    // An image this device just uploaded renders from its local copy (by attachment id), so the
    // canonical message neither re-downloads it nor asks for the signed inline URL.
    val sentImages = build.raft.app.image.RaftSentAttachmentLocalImages.registry
    val localModelFlow = remember(attachment.id) { sentImages.localModelFlow(attachment.id) }
    val localModel by localModelFlow.collectAsState(initial = sentImages.localModel(attachment.id))
    val sourcePlan =
        threadInlineImageSourcePlan(
            thumbnailUrl = attachment.thumbnailUrl,
            fallbackUrl = fallbackUrl,
            localModel = localModel
        )
    val fallbackHostAvailable = fallbackHost != null
    LaunchedEffect(attachment.id, sourcePlan.requestRemoteFallback, fallbackHostAvailable) {
        if (fallbackHostAvailable && sourcePlan.requestRemoteFallback) {
            fallbackHost?.requestFallback?.invoke(attachment.id)
        }
    }
    // The frame (fill, border, radius, press) is RaftMessageImageFrame's; the surface only
    // draws the image, so it brings no fill or border of its own.
    RaftAspectFitImagePreviewSurface(
        source = sourcePlan.source,
        fallbackSource = sourcePlan.fallbackSource,
        contentDescription = attachment.name,
        modifier = Modifier.fillMaxSize(),
        backgroundColor = Color.Transparent,
        borderWidth = 0.dp,
        contentScale = if (fit == RaftMessageImageFit.Cover) RaftImageThumbnailContentScale else ContentScale.Fit,
        onImageStateChange = { state ->
            if (state is AsyncImagePainter.State.Error && fallbackUrl == null) {
                fallbackHost?.requestFallback?.invoke(attachment.id)
            }
        }
    )
}

@Composable
private fun ThreadAttachmentChip(
    attachment: RaftThreadAttachmentItem,
    openState: ThreadAttachmentOpenUiState?,
    onOpen: () -> Unit,
    onDownload: () -> Unit = {}
) {
    if (attachment.isPreviewableVideoAttachment()) {
        ThreadInlineVideoAttachmentCard(
            attachment = attachment,
            onDownload = onDownload
        )
        return
    }
    if (attachment.isPreviewableAudioAttachment()) {
        ThreadInlineAudioAttachmentCard(
            attachment = attachment,
            onDownload = onDownload
        )
        return
    }
    val isOpening = openState.threadAttachmentIsOpening()
    val meta = attachment.threadAttachmentChipMetaLine(stringResource(MR.strings.file_preview_html))
    // A download started on the file page keeps running in the download centre; the card only
    // mirrors it (task #75). The card itself never downloads.
    val downloadHost = LocalThreadAttachmentDownloadHost.current
    val centerEntryFlow = remember(downloadHost, attachment.id) { downloadHost?.entry(attachment.id) }
    val centerEntry = centerEntryFlow?.collectAsState(initial = null)?.value
    val centerLabel =
        raftThreadAttachmentCardDownloadLabel(
            entry = centerEntry,
            terms =
                RaftFilePreviewDownloadStatusTerms(
                    downloading = stringResource(MR.strings.file_preview_download_downloading),
                    paused = stringResource(MR.strings.file_preview_download_paused),
                    saving = stringResource(MR.strings.file_preview_download_saving)
                )
        )
    // Download progress and open failures take the size's place on the meta line, as the web's
    // "Uploading · 64%" does.
    val statusLabel = centerLabel ?: openState.localizedThreadAttachmentStatusLabel()
    // raft-ui MessageAttachmentCard: one affordance icon, Eye for a file with an in-app preview,
    // Download for one that opens its file page. Both only open the page (web AttachmentChip).
    val route = attachment.threadAttachmentOpenRoute()
    val affordance =
        if (route is RaftThreadAttachmentOpenRoute.Preview) {
            RaftAttachmentPreviewCardAction(
                RaftLucideIconName.Eye,
                "${stringResource(MR.strings.file_preview_action_open)} ${attachment.name}",
                onOpen
            )
        } else {
            RaftAttachmentPreviewCardAction(
                RaftLucideIconName.Download,
                "${stringResource(MR.strings.file_preview_action_download)} ${attachment.name}",
                onOpen
            )
        }
    RaftAttachmentPreviewCard(
        title = attachment.name,
        meta = statusLabel ?: meta,
        actions = listOf(affordance),
        loading = isOpening || centerEntry?.status == RaftDownloadStatus.Downloading,
        failed = centerLabel == null && openState.threadAttachmentOpenFailed(),
        onClick = if (isOpening) ({}) else onOpen
    )
}

@Composable
internal fun ThreadAttachmentCommentsSheet(
    state: ThreadAttachmentCommentsDialogState,
    onDismiss: () -> Unit,
    onFilterChange: (String) -> Unit,
    onDraftChange: (TextFieldValue) -> Unit,
    onRetry: () -> Unit,
    onSend: () -> Unit,
    onResolve: (ThreadAttachmentCommentItem) -> Unit,
    onQuote: (ThreadAttachmentCommentItem) -> Unit
) {
    // Read before entering Modal: its content is rehosted in a native window where the
    // page host's safe-area locals are gone (same caveat as RaftUnifiedDialog).
    val bottomInset = raftBottomSafeAreaPadding()
    // Not Kuikly's ModalBottomSheet: its Dialog hard-codes dismissOnClickOutside, which on
    // iOS turns the whole window into one accessibility leaf and hides the comment editor
    // (see raftModalDialogPropertiesWithoutScrim). Modal + RaftModalDismissBarrier is the established
    // bottom-sheet pattern for content with text fields.
    Modal(onWillDismiss = { onDismiss() }) {
        Box(modifier = Modifier.fillMaxSize()) {
            RaftModalDismissBarrier(overlayAlpha = 0.60f, onDismiss = onDismiss)
            Box(
                modifier =
                    Modifier
                        .align(Alignment.BottomCenter)
                        .fillMaxWidth()
                        .padding(start = 12.dp, end = 12.dp, bottom = bottomInset + RaftAppSpacing.Sm)
                        .raftDialogContentPointerBarrier()
            ) {
                // raft-ui dialog surface: dialog radius, popover layer, seam ring, float shadow.
                Column(
                    modifier =
                        Modifier
                            .fillMaxWidth()
                            .raftLookOverlaySurface(RaftAppRadius.Dialog)
                            .padding(18.dp),
                    verticalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(12.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text(
                            text = stringResource(MR.strings.thread_comments_title),
                            style =
                                RaftType.PageTitle.copy(
                                    fontSize = 18.sp,
                                    lineHeight = 22.sp,
                                    color = RaftColor.TextBlack
                                ),
                            color = RaftColor.TextBlack,
                            modifier = Modifier.weight(1f),
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis
                        )
                        RaftBackButton(
                            onClick = onDismiss,
                            label = stringResource(MR.strings.common_close),
                            glyph = RaftGlyph.X,
                        )
                    }
                    ThreadAttachmentCommentsContent(
                        state = state,
                        onFilterChange = onFilterChange,
                        onDraftChange = onDraftChange,
                        onRetry = onRetry,
                        onSend = onSend,
                        onResolve = onResolve,
                        onQuote = onQuote
                    )
                }
            }
        }
    }
}

@Composable
internal fun ThreadAttachmentCommentsContent(
    state: ThreadAttachmentCommentsDialogState,
    onFilterChange: (String) -> Unit,
    onDraftChange: (TextFieldValue) -> Unit,
    onRetry: () -> Unit,
    onSend: () -> Unit,
    onResolve: (ThreadAttachmentCommentItem) -> Unit,
    onQuote: (ThreadAttachmentCommentItem) -> Unit,
    compact: Boolean = false
) {
    val userFacingErrorLabels = threadUserFacingErrorLabels()
    val page = state.page
    val comments =
        remember(state.filter, page?.comments) {
            val all = page?.comments.orEmpty()
            if (state.filter == "unresolved") {
                all.filterNot { it.isThreadAttachmentCommentResolved() }
            } else {
                all
            }
        }
    val viewerCanComment = page?.viewer?.canComment ?: state.status == "loading"
    val commentsListHeight =
        if (compact) {
            when {
                comments.isEmpty() -> 84.dp
                comments.size == 1 -> 150.dp
                else -> 180.dp
            }
        } else {
            threadAttachmentCommentsListHeight(comments.size)
        }
    Column(modifier = Modifier.fillMaxWidth(), verticalArrangement = Arrangement.spacedBy(10.dp)) {
        ThreadAttachmentCommentsHeader(state.attachment)
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.spacedBy(RaftAppSpacing.Xs),
            verticalAlignment = Alignment.CenterVertically
        ) {
            ThreadAttachmentCommentsFilterChip(
                label = stringResource(MR.strings.thread_comments_filter_all),
                selected = state.filter != "unresolved",
                onClick = { onFilterChange("all") }
            )
            ThreadAttachmentCommentsFilterChip(
                label = stringResource(MR.strings.thread_comments_filter_unresolved),
                selected = state.filter == "unresolved",
                onClick = { onFilterChange("unresolved") }
            )
        }
        when (state.status) {
            "loading" ->
                ThreadStateMessage(stringResource(MR.strings.thread_comments_loading), null)
            "error" ->
                ThreadStateActionMessage(
                    title = stringResource(MR.strings.thread_comments_load_failed),
                    detail =
                        attachmentCommentsVisibleErrorMessage(
                            errorCode = state.errorCode,
                            serverMessage = state.errorServerMessage,
                            labels = userFacingErrorLabels,
                            genericMessage = stringResource(MR.strings.common_error)
                        ),
                    actionLabel = stringResource(MR.strings.common_retry),
                    onClick = onRetry
                )
            else ->
                RaftModalListShell(height = commentsListHeight) {
                    if (comments.isEmpty()) {
                        item {
                            ThreadModalEmptyState(
                                title = stringResource(MR.strings.thread_state_no_comments),
                                detail =
                                    if (state.filter == "unresolved") {
                                        stringResource(MR.strings.thread_comments_all_resolved)
                                    } else {
                                        stringResource(MR.strings.thread_comments_start_below)
                                    }
                            )
                        }
                    } else {
                        items(comments.size, key = { comments[it].id }) { index ->
                            ThreadAttachmentCommentRow(
                                comment = comments[index],
                                canComment = viewerCanComment,
                                resolving = comments[index].id in state.resolvingCommentIds,
                                onResolve = { onResolve(comments[index]) },
                                onQuote = { onQuote(comments[index]) }
                            )
                        }
                    }
                }
        }
        state.errorCode?.takeIf { state.status != "error" && it.isNotBlank() }?.let { code ->
            Text(
                text =
                    attachmentCommentsVisibleErrorMessage(
                        errorCode = code,
                        serverMessage = state.errorServerMessage,
                        labels = userFacingErrorLabels,
                        genericMessage = stringResource(MR.strings.common_error)
                    ),
                style = RaftType.Caption.withRaftFontWeight(FontWeight.Bold).copy(color = RaftColor.AccentRed),
                color = RaftColor.AccentRed,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis
            )
        }
        ThreadAttachmentCommentComposer(
            state = state,
            canComment = page?.viewer?.canComment ?: true,
            reason = page?.viewer?.reason,
            onDraftChange = onDraftChange,
            onSend = onSend,
            compact = compact
        )
    }
}

@Composable
private fun ThreadAttachmentCommentsHeader(attachment: RaftThreadAttachmentItem) {
    Row(
        modifier = Modifier.fillMaxWidth()
            .raftCardSurface(fill = RaftColor.FillMuted, radius = RaftAppRadius.Control)
            .padding(horizontal = RaftAppSpacing.Sm, vertical = RaftAppSpacing.Xs),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(8.dp)
    ) {
        RaftLucideIcon(RaftLucideIconName.FileText, modifier = Modifier.size(15.dp), color = RaftColor.TextBlackArgb)
        Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
            Text(
                text = attachment.name,
                style = RaftType.Button.copy(color = RaftColor.TextBlack),
                color = RaftColor.TextBlack,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis
            )
            val meta = attachment.displaySizeLabel()
            if (meta.isNotBlank()) {
                Text(
                    text = meta,
                    style = RaftType.Caption.copy(color = RaftColor.TextMutedGray),
                    color = RaftColor.TextMutedGray,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis
                )
            }
        }
    }
}

