                subtitle = stringResource(MR.strings.thread_settings_archive_detail)
            )
        "delete" ->
            copy(
                title = stringResource(MR.strings.thread_settings_delete),
                subtitle = stringResource(MR.strings.thread_settings_delete_detail)
            )
        else -> this
    }

